async function evaluate(ctx: RuleContext<'P-01'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const project = await ctx.db.project.findById(massid.projectId);
  if (!project) {
    return ctx.fail({ ruleId: 'P-01', severity: 'BLOCK',
      message: 'No project linked to MassID', field: 'projectId' });
  }
  const completion = massid.completionDate;
  if (completion == null) {
    return ctx.fail({ ruleId: 'P-01', severity: 'BLOCK',
      message: 'completion_date missing', field: 'completionDate' });
  }
  if (completion < project.startDate || completion > project.endDate) {
    return ctx.fail({ ruleId: 'P-01', severity: 'BLOCK',
      message: `completion_date ${completion.toISOString()} outside project window [${project.startDate.toISOString()}, ${project.endDate.toISOString()}]`,
      field: 'completionDate' });
  }
  return ctx.pass({ ruleId: 'P-01' });
}

async function evaluate(ctx: RuleContext<'P-02'>): Promise<RuleResult> {
  const chain = await ctx.db.getChainParticipants(ctx.input.massidId);
  const eventDate = ctx.input.eventDate ?? ctx.now;
  const RELEVANT_ROLES = ['R', 'P', 'INT'];
  const issues: Array<{pid: string; reason: string}> = [];
  for (const p of chain) {
    if (!RELEVANT_ROLES.includes(p.role)) continue;
    if (p.homologationStatus !== 'active') {
      issues.push({ pid: p.id, reason: `status=${p.homologationStatus ?? 'null'}` });
      continue;
    }
    if (p.homologationExpiry && p.homologationExpiry < eventDate) {
      issues.push({ pid: p.id, reason: `expired ${p.homologationExpiry.toISOString()}` });
    }
    const doc = await ctx.db.document.findFirst({ where: {
      participantId: p.id, type: 'homologation_record'
    }});
    if (!doc) issues.push({ pid: p.id, reason: 'homologation_record missing' });
  }
  if (issues.length > 0) {
    return ctx.fail({ ruleId: 'P-02', severity: 'BLOCK',
      message: `Homologation invalid for ${issues.length} participants: ${issues.map(i => `${i.pid}(${i.reason})`).join('; ')}`,
      field: 'homologationStatus' });
  }
  return ctx.pass({ ruleId: 'P-02' });
}

async function evaluate(ctx: RuleContext<'P-03'>): Promise<RuleResult> {
  const p = ctx.participant;
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';

  if (p.kycStatus !== 'complete') {
    return ctx.fail({ ruleId: 'P-03', severity: sev,
      message: isProd ? 'KYC/KYB nao completo — bloqueia operacao'
                       : 'AVISO sandbox: KYC/KYB nao completo (em prod isso bloquearia)',
      field: 'participant.kycStatus' });
  }
  const rec = await ctx.db.document.findOne({ where: {
    type: 'kyc_kyb_record', participantId: p.id
  }});
  if (!rec) {
    return ctx.fail({ ruleId: 'P-03', severity: sev,
      message: 'kyc_kyb_record document missing',
      field: 'documents.kyc_kyb_record' });
  }
  if (rec.kycValidUntil && rec.kycValidUntil < ctx.now) {
    return ctx.fail({ ruleId: 'P-03', severity: sev,
      message: `KYC expired on ${rec.kycValidUntil.toISOString()}. Renew before continuing.`,
      field: 'kyc_kyb_record.kycValidUntil' });
  }
  return ctx.pass({ ruleId: 'P-03' });
}

async function evaluate(ctx: RuleContext<'P-04'>): Promise<RuleResult> {
  const massid = ctx.input.massid;
  if (!massid.hash) {
    return ctx.fail({ ruleId: 'P-04', severity: 'BLOCK',
      message: 'MassID hash missing — cannot verify uniqueness', field: 'hash' });
  }
  const existing = await ctx.targetRegistry.findTokenByMassidHash(massid.hash);
  if (existing) {
    return ctx.fail({ ruleId: 'P-04', severity: 'BLOCK',
      message: `TRC already issued for this MassID (token ${existing.tokenId})`,
      field: 'hash' });
  }
  const localToken = await ctx.db.tokenRegistry.findFirst({ where: { massidHash: massid.hash }});
  if (localToken) {
    return ctx.fail({ ruleId: 'P-04', severity: 'BLOCK',
      message: `TRC issuance in flight for this MassID (local token ${localToken.id})`,
      field: 'hash' });
  }
  return ctx.pass({ ruleId: 'P-04' });
}

async function evaluate(ctx: RuleContext<'P-05'>): Promise<RuleResult> {
  const p = ctx.participant;
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';

  if (!p.exclusivityFlag) {
    return ctx.fail({ ruleId: 'P-05', severity: sev,
      message: isProd ? 'Falta aceite de exclusividade.'
                       : 'AVISO sandbox: falta aceite de exclusividade.',
      field: 'participant.exclusivityFlag' });
  }
  const ack = await ctx.db.document.findOne({ where: {
    type: 'contract_exclusivity_ack', participantId: p.id
  }});
  if (!ack) {
    return ctx.fail({ ruleId: 'P-05', severity: sev,
      message: 'contract_exclusivity_ack document missing',
      field: 'documents.contract_exclusivity_ack' });
  }

  // Validar exclusividade no MOMENTO do pickup (não no now).
  // Revogação não é retroativa: lotes submetidos antes de revokeEffectiveAt permanecem válidos.
  const pickupAt = ctx.massId?.pickupAt ?? ctx.now;
  if (pickupAt < ack.acceptedAt) {
    return ctx.fail({ ruleId: 'P-05', severity: sev,
      message: `Aceite assinado em ${ack.acceptedAt.toISOString()} é posterior ao pickup do lote (${pickupAt.toISOString()}). Lote anterior ao aceite.`,
      field: 'contract_exclusivity_ack.acceptedAt' });
  }
  if (ack.revokeEffectiveAt && pickupAt >= ack.revokeEffectiveAt) {
    return ctx.fail({ ruleId: 'P-05', severity: sev,
      message: `Aceite revogado em ${ack.revokeEffectiveAt.toISOString()}. Lote pickup posterior à revogação.`,
      field: 'contract_exclusivity_ack.revokeEffectiveAt' });
  }

  // Versionamento: re-aceite obrigatório se versão major do termo mudou.
  const currentTermsMajor = ctx.config.currentTermsVersion.split('.')[0];
  const ackMajor = ack.termsVersion.split('.')[0];
  if (currentTermsMajor !== ackMajor) {
    return ctx.fail({ ruleId: 'P-05', severity: sev,
      message: `Termo atualizado para versão ${ctx.config.currentTermsVersion}. Re-aceite obrigatório.`,
      field: 'contract_exclusivity_ack.termsVersion' });
  }
  return ctx.pass({ ruleId: 'P-05' });
}

async function evaluate(ctx: RuleContext<'P-06'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const issues: string[] = [];
  if (m.grossKg == null || !Number.isFinite(m.grossKg) || m.grossKg <= 0) {
    issues.push(`gross_kg=${m.grossKg}`);
  }
  if (m.netKg == null || !Number.isFinite(m.netKg) || m.netKg <= 0) {
    issues.push(`net_kg=${m.netKg}`);
  }
  if (issues.length > 0) {
    return ctx.fail({ ruleId: 'P-06', severity: 'BLOCK',
      message: `MassID weight invalid: ${issues.join(', ')} (must be > 0)`,
      field: issues[0].startsWith('gross') ? 'grossKg' : 'netKg' });
  }
  return ctx.pass({ ruleId: 'P-06' });
}

async function evaluate(ctx: RuleContext<'P-07'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid) {
    return ctx.fail({ ruleId: 'P-07', severity: 'BLOCK',
      message: 'MassID not found', field: 'massidId' });
  }
  const uom = massid.uom;
  if (uom == null || String(uom).trim() === '') {
    return ctx.fail({ ruleId: 'P-07', severity: 'BLOCK',
      message: 'Unit of measure (uom) is required',
      field: 'uom' });
  }
  if (uom !== 'kg') {
    return ctx.fail({ ruleId: 'P-07', severity: 'BLOCK',
      message: `Unit of measure must be 'kg', got '${uom}'`,
      field: 'uom' });
  }
  return ctx.pass({ ruleId: 'P-07' });
}

async function evaluate(ctx: RuleContext<'P-08'>): Promise<RuleResult> {
  const doc = await ctx.db.document.findById(ctx.input.documentId);
  if (!doc) {
    return ctx.fail({ ruleId: 'P-08', severity: 'BLOCK',
      message: 'Document not found', field: 'documentId' });
  }
  if (doc.category == null || String(doc.category).trim() === '') {
    return ctx.fail({ ruleId: 'P-08', severity: 'BLOCK',
      message: 'Document.category is required', field: 'category' });
  }
  if (doc.category !== 'MassID') {
    return ctx.fail({ ruleId: 'P-08', severity: 'BLOCK',
      message: `Document.category must be 'MassID', got '${doc.category}'`,
      field: 'category' });
  }
  return ctx.pass({ ruleId: 'P-08' });
}

async function evaluate(ctx: RuleContext<'P-09'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid) {
    return ctx.fail({ ruleId: 'P-09', severity: 'BLOCK',
      message: 'MassID not found', field: 'massidId' });
  }
  const cls = massid.materialClass;
  if (cls == null || String(cls).trim() === '') {
    return ctx.fail({ ruleId: 'P-09', severity: 'BLOCK',
      message: 'material_class is required', field: 'materialClass' });
  }
  if (cls !== 'plastic') {
    return ctx.fail({ ruleId: 'P-09', severity: 'BLOCK',
      message: `material_class must be 'plastic' for PURE, got '${cls}'`,
      field: 'materialClass' });
  }
  return ctx.pass({ ruleId: 'P-09' });
}

async function evaluate(ctx: RuleContext<'P-10'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const required = ['streamClass', 'originClass'];
  const missing = required.filter(f => !massid[f] || String(massid[f]).trim() === '');
  if (missing.length) {
    return ctx.fail({ ruleId: 'P-10', severity: 'BLOCK',
      message: `Waste stream classification missing fields: ${missing.join(', ')}`,
      field: missing[0] });
  }
  const STREAM_VALUES = ['single_polymer','mixed','composite','byproduct','residual'];
  const ORIGIN_VALUES = ['residential','commercial','industrial','marine','open_dump'];
  if (!STREAM_VALUES.includes(massid.streamClass)) {
    return ctx.fail({ ruleId: 'P-10', severity: 'BLOCK',
      message: `streamClass '${massid.streamClass}' not in approved enum`,
      field: 'streamClass' });
  }
  if (!ORIGIN_VALUES.includes(massid.originClass)) {
    return ctx.fail({ ruleId: 'P-10', severity: 'BLOCK',
      message: `originClass '${massid.originClass}' not in approved enum`,
      field: 'originClass' });
  }
  return ctx.pass({ ruleId: 'P-10' });
}

async function evaluate(ctx: RuleContext<'P-11'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const value = massid.resinType;
  if (value == null || String(value).trim() === '') {
    return ctx.fail({ ruleId: 'P-11', severity: 'BLOCK',
      message: 'resin_type is required', field: 'resinType' });
  }
  const APPROVED = ['PET','HDPE','PVC','LDPE','PP','PS','EPS','Other'];
  if (!APPROVED.includes(value)) {
    return ctx.fail({ ruleId: 'P-11', severity: 'BLOCK',
      message: `resin_type '${value}' not in approved enum [${APPROVED.join(', ')}]`,
      field: 'resinType' });
  }
  return ctx.pass({ ruleId: 'P-11' });
}

async function evaluate(ctx: RuleContext<'P-12'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (massid.resinType !== 'Other') {
    return ctx.skip({ reason: 'resinType is not Other; rule does not apply.' });
  }
  const subtype = massid.resinSubtype;
  if (subtype == null || String(subtype).trim() === '') {
    return ctx.fail({ ruleId: 'P-12', severity: 'BLOCK',
      message: 'resin_subtype is required when resin_type=Other',
      field: 'resinSubtype' });
  }
  if (String(subtype).trim().length < 3) {
    return ctx.fail({ ruleId: 'P-12', severity: 'BLOCK',
      message: 'resin_subtype must be descriptive (>=3 chars)',
      field: 'resinSubtype' });
  }
  return ctx.pass({ ruleId: 'P-12' });
}

async function evaluate(ctx: RuleContext<'P-13'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid.isComposite) {
    return ctx.skip({ reason: 'Not a composite; rule does not apply.' });
  }
  if (massid.primaryPlasticFlag !== true) {
    return ctx.fail({ ruleId: 'P-13', severity: 'BLOCK',
      message: 'Composite must have primary plastic component (primaryPlasticFlag=true)',
      field: 'primaryPlasticFlag' });
  }
  const comp = massid.compositionJson;
  if (comp == null || (Array.isArray(comp) && comp.length === 0) || Object.keys(comp || {}).length === 0) {
    return ctx.fail({ ruleId: 'P-13', severity: 'BLOCK',
      message: 'composition_json is required for composite MassID',
      field: 'compositionJson' });
  }
  return ctx.pass({ ruleId: 'P-13' });
}

async function evaluate(ctx: RuleContext<'P-14'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid.isMixed) {
    return ctx.skip({ reason: 'Not a mixed MassID; rule does not apply.' });
  }
  const recycler = await ctx.db.participant.findById(massid.recyclerId);
  if (!recycler) {
    return ctx.fail({ ruleId: 'P-14', severity: 'BLOCK',
      message: 'Recycler not found for mixed MassID', field: 'recyclerId' });
  }
  if (recycler.acceptsMixed !== true) {
    return ctx.fail({ ruleId: 'P-14', severity: 'BLOCK',
      message: `Recycler ${recycler.id} does not accept mixed plastic input`,
      field: 'recycler.acceptsMixed' });
  }
  return ctx.pass({ ruleId: 'P-14' });
}

async function evaluate(ctx: RuleContext<'P-15'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const triggers = massid.isComposite || massid.mixedWithDebris;
  if (!triggers) {
    return ctx.skip({ reason: 'Not composite or debris-mixed; rule does not apply.' });
  }
  const factor = massid.plasticContentFactor;
  if (factor == null) {
    return ctx.fail({ ruleId: 'P-15', severity: 'BLOCK',
      message: 'plastic_content_factor is required for composite/debris MassID',
      field: 'plasticContentFactor' });
  }
  if (typeof factor !== 'number' || isNaN(factor)) {
    return ctx.fail({ ruleId: 'P-15', severity: 'BLOCK',
      message: 'plastic_content_factor must be numeric',
      field: 'plasticContentFactor' });
  }
  if (factor <= 0 || factor > 1) {
    return ctx.fail({ ruleId: 'P-15', severity: 'BLOCK',
      message: `plastic_content_factor must be in (0, 1], got ${factor}`,
      field: 'plasticContentFactor' });
  }
  return ctx.pass({ ruleId: 'P-15' });
}

async function evaluate(ctx: RuleContext<'P-16'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const p15Triggered = massid.isComposite || massid.mixedWithDebris;
  if (!p15Triggered) {
    return ctx.skip({ reason: 'P-15 not triggered; rule does not apply.' });
  }
  const REQUIRED_DOCS = ['sampling_report', 'lab_composition_report', 'protocol_reference', 'auditor_validation'];
  const docs = await ctx.db.document.findMany({
    where: { massidId: massid.id, type: { in: REQUIRED_DOCS } }
  });
  const present = new Set(docs.map(d => d.type));
  const missing = REQUIRED_DOCS.filter(t => !present.has(t));
  if (missing.length) {
    return ctx.fail({ ruleId: 'P-16', severity: 'BLOCK',
      message: `Adjustment factor evidence pack missing: ${missing.join(', ')}`,
      field: 'documents' });
  }
  return ctx.pass({ ruleId: 'P-16' });
}

async function evaluate(ctx: RuleContext<'P-17'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (massid.hazardFlag !== true) {
    return ctx.pass({ ruleId: 'P-17' });
  }
  const method = massid.decontaminationMethod;
  if (method == null || String(method).trim() === '') {
    return ctx.fail({ ruleId: 'P-17', severity: 'BLOCK',
      message: 'Hazardous MassID requires declared decontamination method',
      field: 'decontaminationMethod' });
  }
  const approval = await ctx.db.document.findFirst({
    where: { massidId: massid.id, type: 'decontamination_approval' }
  });
  if (!approval) {
    return ctx.fail({ ruleId: 'P-17', severity: 'BLOCK',
      message: 'decontamination_approval document missing',
      field: 'documents' });
  }
  return ctx.pass({ ruleId: 'P-17' });
}

async function evaluate(ctx: RuleContext<'P-18'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid.recyclerId) {
    return ctx.fail({ ruleId: 'P-18', severity: 'BLOCK',
      message: 'recycler_id missing on MassID', field: 'recyclerId' });
  }
  if (massid.chainComplete !== true) {
    return ctx.fail({ ruleId: 'P-18', severity: 'BLOCK',
      message: 'Custody chain incomplete', field: 'chainComplete' });
  }
  const recycler = await ctx.db.participant.findById(massid.recyclerId);
  if (!recycler) {
    return ctx.fail({ ruleId: 'P-18', severity: 'BLOCK',
      message: 'Recycler not found', field: 'recyclerId' });
  }
  const permit = await ctx.db.document.findFirst({
    where: { participantId: recycler.id, type: 'recycler_permit' }
  });
  if (!permit) {
    return ctx.fail({ ruleId: 'P-18', severity: 'BLOCK',
      message: 'recycler_permit document missing', field: 'documents' });
  }
  if (permit.validUntil && permit.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'P-18', severity: 'BLOCK',
      message: `recycler_permit expired on ${permit.validUntil.toISOString()}`,
      field: 'permit.validUntil' });
  }
  return ctx.pass({ ruleId: 'P-18' });
}

async function evaluate(ctx: RuleContext<'P-19'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const code = massid.finalOutcomeCode;
  if (code == null || String(code).trim() === '') {
    return ctx.fail({ ruleId: 'P-19', severity: 'BLOCK',
      message: 'final_outcome_code is required at POST_RECYCLING',
      field: 'finalOutcomeCode' });
  }
  const DISPOSAL_CODES = ['landfill','incineration','fuel_recovery','energy_recovery','dumped','unaccounted'];
  if (DISPOSAL_CODES.includes(code)) {
    return ctx.fail({ ruleId: 'P-19', severity: 'BLOCK',
      message: `MassID outcome '${code}' is a disposal code; not eligible for PURE credit`,
      field: 'finalOutcomeCode' });
  }
  const ALLOWED = ['recycled','transformed','upcycled','downcycled','closed_loop'];
  if (!ALLOWED.includes(code)) {
    return ctx.fail({ ruleId: 'P-19', severity: 'BLOCK',
      message: `final_outcome_code '${code}' not in allowed enum [${ALLOWED.join(', ')}]`,
      field: 'finalOutcomeCode' });
  }
  return ctx.pass({ ruleId: 'P-19' });
}

async function evaluate(ctx: RuleContext<'P-20'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const generator = await ctx.db.participant.findFirst({ where: {
    massidId: m.id, role: 'G'
  }});
  const known = m.originKnownFlag === true;
  if (known && !generator) {
    return ctx.fail({ ruleId: 'P-20', severity: 'BLOCK',
      message: 'origin_known_flag=TRUE but no Generator declared',
      field: 'generatorId' });
  }
  if (!known && generator) {
    return ctx.fail({ ruleId: 'P-20', severity: 'BLOCK',
      message: 'origin_known_flag=FALSE but Generator declared (use unidentified flow)',
      field: 'originKnownFlag' });
  }
  if (m.originKnownFlag == null) {
    return ctx.fail({ ruleId: 'P-20', severity: 'BLOCK',
      message: 'origin_known_flag is required', field: 'originKnownFlag' });
  }
  return ctx.pass({ ruleId: 'P-20' });
}

async function evaluate(ctx: RuleContext<'P-21'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (m.originKnownFlag !== true) {
    return ctx.skip({ reason: 'origin_known_flag != TRUE; delegated to P-20' });
  }
  const generators = await ctx.db.participant.count({ where: {
    massidId: m.id, role: 'G'
  }});
  if (generators !== 1) {
    return ctx.fail({ ruleId: 'P-21', severity: 'BLOCK',
      message: `generator_count=${generators}, expected exactly 1 when origin is identified`,
      field: 'participants' });
  }
  return ctx.pass({ ruleId: 'P-21' });
}

async function evaluate(ctx: RuleContext<'P-22'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.primaryParticipantId || !m.firstPickupActorId) {
    return ctx.fail({ ruleId: 'P-22', severity: 'BLOCK',
      message: 'primary_participant_id or first_pickup_actor_id missing',
      field: 'primaryParticipantId' });
  }
  if (m.primaryParticipantId !== m.firstPickupActorId) {
    return ctx.fail({ ruleId: 'P-22', severity: 'BLOCK',
      message: `primary_participant_id (${m.primaryParticipantId}) does not match first_pickup_actor_id (${m.firstPickupActorId})`,
      field: 'primaryParticipantId' });
  }
  return ctx.pass({ ruleId: 'P-22' });
}

async function evaluate(ctx: RuleContext<'P-23'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.primaryAddressId || !m.firstPickupAddressId) {
    return ctx.fail({ ruleId: 'P-23', severity: 'BLOCK',
      message: 'primary_address_id or first_pickup_address_id missing',
      field: 'primaryAddressId' });
  }
  if (m.primaryAddressId !== m.firstPickupAddressId) {
    const a1 = await ctx.db.address.findById(m.primaryAddressId);
    const a2 = await ctx.db.address.findById(m.firstPickupAddressId);
    return ctx.fail({ ruleId: 'P-23', severity: 'BLOCK',
      message: `primary_address_id (${a1?.label ?? m.primaryAddressId}) does not match first_pickup_address_id (${a2?.label ?? m.firstPickupAddressId})`,
      field: 'primaryAddressId' });
  }
  return ctx.pass({ ruleId: 'P-23' });
}

async function evaluate(ctx: RuleContext<'P-24'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const recyclers = await ctx.db.participant.count({ where: {
    massidId: m.id, role: 'R'
  }});
  if (recyclers !== 1) {
    return ctx.fail({ ruleId: 'P-24', severity: 'BLOCK',
      message: `recycler_count=${recyclers}, expected exactly 1`,
      field: 'participants' });
  }
  return ctx.pass({ ruleId: 'P-24' });
}

async function evaluate(ctx: RuleContext<'P-25'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const hasTransport = await ctx.db.transportLeg.count({ where: { massidId: m.id }}) > 0;
  if (!hasTransport) {
    return ctx.skip({ reason: 'No transport leg; rule does not apply' });
  }
  const haulers = await ctx.db.participant.count({ where: {
    massidId: m.id, role: 'H'
  }});
  if (haulers >= 1) return ctx.pass({ ruleId: 'P-25' });
  if (m.generatorAsHaulerFlag === true) return ctx.pass({ ruleId: 'P-25' });
  return ctx.fail({ ruleId: 'P-25', severity: 'BLOCK',
    message: 'Transport exists but no Hauler declared and generator_as_hauler_flag is not set',
    field: 'haulers' });
}

async function evaluate(ctx: RuleContext<'P-26'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (m.processorStepExists !== true) {
    return ctx.skip({ reason: 'No processor step; rule does not apply' });
  }
  const processors = await ctx.db.participant.findMany({ where: {
    massidId: m.id, role: 'P'
  }});
  if (processors.length < 1) {
    return ctx.fail({ ruleId: 'P-26', severity: 'BLOCK',
      message: 'processor_step_exists=TRUE but no Processor declared',
      field: 'participants' });
  }
  const notActive = processors.filter(p => p.homologationStatus !== 'active');
  if (notActive.length > 0) {
    return ctx.fail({ ruleId: 'P-26', severity: 'BLOCK',
      message: `Processor(s) without active homologation: ${notActive.map(p => p.id).join(', ')}`,
      field: 'homologationStatus' });
  }
  for (const p of processors) {
    const doc = await ctx.db.document.findFirst({ where: {
      participantId: p.id, type: 'homologation_record'
    }});
    if (!doc) {
      return ctx.fail({ ruleId: 'P-26', severity: 'BLOCK',
        message: `homologation_record missing for Processor ${p.id}`,
        field: 'documents' });
    }
  }
  return ctx.pass({ ruleId: 'P-26' });
}

