async function evaluate(ctx: RuleContext<'P-29'>): Promise<RuleResult> {
  const event = await ctx.db.massIDEvent.findById(ctx.input.pickupEventId);
  if (!event) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: 'Pickup event not found', field: 'pickupEventId' });
  }
  if (event.lat == null || event.lon == null) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: 'GPS coordinates missing on pickup event', field: 'lat' });
  }
  const precision = ctx.geo.getPrecision(event.lat, event.lon);
  if (precision > ctx.config.maxGeoPrecisionMeters) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: `GPS precision too coarse (${precision}m > ${ctx.config.maxGeoPrecisionMeters}m)`,
      field: 'lat' });
  }
  if (event.sourceType === 'business') {
    const inside = await ctx.geo.isInsideDropOff(event.lat, event.lon);
    if (!inside) {
      return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
        message: 'Business pickup GPS outside any active DropOffPoint',
        field: 'lat' });
    }
  }
  return ctx.pass({ ruleId: 'P-29' });
}

