    return ctx.skip({ reason: 'No weigh event.' });
  }
  const events = await ctx.db.weighEvent.findMany({ where: { massidId: massid.id } });
  const REQUIRED = ['grossKg','tareKg','netKg'];
  for (const ev of events) {
    const missing = REQUIRED.filter(f => ev[f] == null);
    if (missing.length) {
      return ctx.fail({ ruleId: 'P-45', severity: 'BLOCK',
        message: `weigh event ${ev.id} missing fields: ${missing.join(', ')}`,
        field: missing[0] });
    }
    if (ev.containerUsed && (ev.containerWeight == null || ev.containerType == null)) {
      return ctx.fail({ ruleId: 'P-45', severity: 'BLOCK',
        message: `weigh event ${ev.id} container_used=true but container fields missing`,
        field: 'containerWeight' });
    }
  }
  return ctx.pass({ ruleId: 'P-45' });
}

async function evaluate(ctx: RuleContext<'P-46'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if ((massid.weighEventCount ?? 0) < 1) {
    return ctx.skip({ reason: 'No weigh event.' });
  }
  const events = await ctx.db.weighEvent.findMany({ where: { massidId: massid.id } });
  const TOLERANCE = ctx.config.netWeightTolerance ?? 0.005;
  for (const ev of events) {
    if (ev.grossKg == null || ev.tareKg == null || ev.netKg == null) {
      return ctx.skip({ reason: 'Fields missing; delegated to P-45.' });
    }
    const expected = ev.grossKg - ev.tareKg;
    const diff = Math.abs(ev.netKg - expected);
    const tol = Math.abs(ev.grossKg) * TOLERANCE;
    if (diff > tol) {
      return ctx.fail({ ruleId: 'P-46', severity: 'BLOCK',
        message: `net_kg (${ev.netKg}) != gross_kg - tare_kg (${expected}) on event ${ev.id}; drift ${(diff/ev.grossKg*100).toFixed(3)}% > tolerance ${TOLERANCE*100}%`,
        field: 'netKg' });
    }
  }
  return ctx.pass({ ruleId: 'P-46' });
}

async function evaluate(ctx: RuleContext<'P-47'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const p15Triggered = massid.isComposite || massid.mixedWithDebris;
  if (!p15Triggered) {
    return ctx.skip({ reason: 'P-15 not triggered; rule does not apply.' });
  }
  const net = massid.netKg;
  const factor = massid.plasticContentFactor;
  const eligible = massid.eligibleKg;
  if (net == null || factor == null || eligible == null) {
    return ctx.fail({ ruleId: 'P-47', severity: 'BLOCK',
      message: 'net_kg, plastic_content_factor and eligible_kg all required',
      field: 'eligibleKg' });
  }
  const expected = net * factor;
  const diff = Math.abs(eligible - expected);
  const TOLERANCE = ctx.config.eligibleWeightTolerance ?? 0.005;
  const tol = Math.abs(expected) * TOLERANCE;
  if (diff > tol) {
    return ctx.fail({ ruleId: 'P-47', severity: 'BLOCK',
      message: `eligible_kg (${eligible}) != net_kg * factor (${expected.toFixed(3)}); drift ${(diff/expected*100).toFixed(3)}% > tolerance ${TOLERANCE*100}%`,
      field: 'eligibleKg' });
  }
  return ctx.pass({ ruleId: 'P-47' });
}

