async function evaluate(ctx: RuleContext<'P-49'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const recycler = await ctx.db.participant.findFirst({ where: {
    massidId: m.id, role: 'R'
  }});
  if (!recycler) {
    return ctx.fail({ ruleId: 'P-49', severity: 'BLOCK',
      message: 'No Recycler in chain', field: 'participants' });
  }
  const issues: string[] = [];
  if (recycler.homologationStatus !== 'active') issues.push(`homologation=${recycler.homologationStatus ?? 'null'}`);
  if (recycler.auditStatus !== 'current') issues.push(`audit=${recycler.auditStatus ?? 'null'}`);
  if (recycler.permitStatus !== 'valid') issues.push(`permit_status=${recycler.permitStatus ?? 'null'}`);
  const permitDoc = await ctx.db.document.findFirst({ where: {
    participantId: recycler.id, type: 'recycler_permit'
  }});
  if (!permitDoc) issues.push('recycler_permit doc missing');
  else if (permitDoc.validUntil && permitDoc.validUntil < ctx.now) {
    issues.push(`recycler_permit expired ${permitDoc.validUntil.toISOString()}`);
  }
  if (issues.length > 0) {
    return ctx.fail({ ruleId: 'P-49', severity: 'BLOCK',
      message: `Recycler ${recycler.id} not qualified: ${issues.join('; ')}`,
      field: 'recyclerQualification' });
  }
  return ctx.pass({ ruleId: 'P-49' });
}

