  if (value == null || String(value).trim() === '') {
    return ctx.fail({ ruleId: 'P-52', severity: 'BLOCK',
      message: 'recycling_manifest_id is required at POST_RECYCLING',
      field: 'recyclingManifestId' });
  }
  return ctx.pass({ ruleId: 'P-52' });
}

async function evaluate(ctx: RuleContext<'P-53'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.recyclingManifestId) {
    return ctx.skip({ reason: 'No manifest id; delegated to P-52' });
  }
  const doc = await ctx.db.document.findFirst({ where: {
    massidId: m.id, type: 'recycling_manifest'
  }});
  if (doc && doc.fileUri) {
    return ctx.pass({ ruleId: 'P-53' });
  }
  if (m.recyclingManifestExemptionFlag === true) {
    return ctx.pass({ ruleId: 'P-53' });
  }
  return ctx.fail({ ruleId: 'P-53', severity: 'BLOCK',
    message: 'recycling_manifest file missing and exemption flag not set',
    field: 'documents' });
}

async function evaluate(ctx: RuleContext<'P-54'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (m.recyclingManifestExemptionFlag !== true) {
    return ctx.skip({ reason: 'exemption flag not set; rule does not apply' });
  }
  const reason = (m.recyclingManifestExemptionReason ?? '').trim();
  if (reason.length === 0) {
    return ctx.fail({ ruleId: 'P-54', severity: 'BLOCK',
      message: 'recycling_manifest_exemption_reason is required when exemption flag is TRUE',
      field: 'recyclingManifestExemptionReason' });
  }
  if (reason.length < 20) {
    return ctx.fail({ ruleId: 'P-54', severity: 'BLOCK',
      message: `exemption reason too short (${reason.length} chars, min 20)`,
      field: 'recyclingManifestExemptionReason' });
  }
  return ctx.pass({ ruleId: 'P-54' });
}

async function evaluate(ctx: RuleContext<'P-55'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const doc = await ctx.db.document.findFirst({ where: { massidId: m.id, type: 'recycling_manifest' }});
  if (!doc) {
    return ctx.skip({ reason: 'No manifest doc; delegated to P-53' });
  }
  const recycler = await ctx.db.participant.findFirst({ where: { massidId: m.id, role: 'R' }});
  if (!recycler) {
    return ctx.skip({ reason: 'No recycler; delegated to P-24' });
  }
  const manifestDest = doc.metadata?.destinationAddressId;
  const recyclerSite = recycler.siteAddressId;
  if (manifestDest === recyclerSite) {
    return ctx.pass({ ruleId: 'P-55' });
  }
  // fallback geo-distance check
  const distance = await ctx.geo.distanceBetween(manifestDest, recyclerSite);
  if (distance != null && distance < 100) {
    return ctx.pass({ ruleId: 'P-55' });
  }
  return ctx.fail({ ruleId: 'P-55', severity: 'BLOCK',
    message: `manifest destination (${manifestDest}) does not match recycler site (${recyclerSite}); distance ${distance ?? 'n/a'}m`,
    field: 'manifestDestination' });
}

async function evaluate(ctx: RuleContext<'P-56'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const doc = await ctx.db.document.findFirst({ where: { massidId: m.id, type: 'recycling_manifest' }});
  if (!doc) {
    return ctx.skip({ reason: 'No manifest doc; delegated to P-53' });
  }
  const required = ['destination', 'material', 'quantity', 'date', 'final_receiver', 'process_reference'];
  const data = doc.metadata ?? {};
  const missing = required.filter(f => data[f] == null || String(data[f]).trim() === '');
  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'P-56', severity: 'BLOCK',
      message: `Recycling manifest missing required fields: ${missing.join(', ')}`,
      field: 'recyclingManifest' });
  }
  return ctx.pass({ ruleId: 'P-56' });
}

async function evaluate(ctx: RuleContext<'P-57'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const manifest = await ctx.db.document.findFirst({ where: { massidId: m.id, type: 'recycling_manifest' }});
  const receipt = await ctx.db.document.findFirst({ where: { massidId: m.id, type: 'recycler_receipt' }});
  if (!manifest || !receipt) {
    return ctx.skip({ reason: 'Required docs missing; delegated to P-52/P-53' });
  }
  const manifestKg = Number(manifest.metadata?.quantity);
  const receivedKg = Number(receipt.metadata?.received_qty);
  const eligibleKg = m.eligibleKg ?? receivedKg;
  const TOL = 0.01; // 1%
  const driftRecv = Math.abs(manifestKg - receivedKg);
  const tolRecv = receivedKg * TOL;
  if (driftRecv > tolRecv) {
    return ctx.fail({ ruleId: 'P-57', severity: 'BLOCK',
      message: `manifest_kg (${manifestKg}) vs received_kg (${receivedKg}) drift ${(driftRecv/receivedKg*100).toFixed(2)}% > tolerance 1%`,
      field: 'manifestKg' });
  }
  const driftElig = Math.abs(manifestKg - eligibleKg);
  const tolElig = eligibleKg * TOL;
  if (driftElig > tolElig) {
    return ctx.fail({ ruleId: 'P-57', severity: 'BLOCK',
      message: `manifest_kg (${manifestKg}) vs eligible_kg (${eligibleKg}) drift ${(driftElig/eligibleKg*100).toFixed(2)}% > tolerance 1%`,
      field: 'manifestKg' });
  }
  return ctx.pass({ ruleId: 'P-57' });
}

async function evaluate(ctx: RuleContext<'P-58'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.recyclingCompleteEventId) {
    return ctx.fail({ ruleId: 'P-58', severity: 'BLOCK',
      message: 'recycling_complete_event required before credit issuance',
      field: 'recyclingCompleteEventId' });
  }
  const event = await ctx.db.massIDEvent.findById(m.recyclingCompleteEventId);
  if (!event || event.type !== 'recycling_complete') {
    return ctx.fail({ ruleId: 'P-58', severity: 'BLOCK',
      message: `Event ${m.recyclingCompleteEventId} not found or wrong type`,
      field: 'recyclingCompleteEventId' });
  }
  return ctx.pass({ ruleId: 'P-58' });
}

async function evaluate(ctx: RuleContext<'P-59'>): Promise<RuleResult> {
  const outcome = await ctx.db.recyclingOutcome.findFirst({ where: { massidId: ctx.input.massidId }});
  if (!outcome) {
    return ctx.fail({ ruleId: 'P-59', severity: 'BLOCK',
      message: 'RecyclingOutcome missing', field: 'recyclingOutcome' });
  }
  const value = outcome.outputType;
  if (value == null || String(value).trim() === '') {
    return ctx.fail({ ruleId: 'P-59', severity: 'BLOCK',
      message: 'output_type is required', field: 'outputType' });
  }
  const APPROVED = ['flake', 'pellet', 'regrind', 'monomer', 'other'];
  if (!APPROVED.includes(value)) {
    return ctx.fail({ ruleId: 'P-59', severity: 'BLOCK',
      message: `output_type '${value}' not in approved enum [${APPROVED.join(', ')}]`,
      field: 'outputType' });
  }
  if (value === 'other' && (!outcome.outputTypeDescription || outcome.outputTypeDescription.trim().length < 10)) {
    return ctx.fail({ ruleId: 'P-59', severity: 'BLOCK',
      message: 'output_type=other requires description (min 10 chars)',
      field: 'outputTypeDescription' });
  }
  return ctx.pass({ ruleId: 'P-59' });
}

async function evaluate(ctx: RuleContext<'P-60'>): Promise<RuleResult> {
  const outcome = await ctx.db.recyclingOutcome.findFirst({ where: { massidId: ctx.input.massidId }});
  if (!outcome) {
    return ctx.skip({ reason: 'No outcome yet; delegated to P-58' });
  }
  const input = outcome.inputKg;
  const output = outcome.outputKg;
  if (!input || input <= 0 || output == null || output < 0) {
    return ctx.fail({ ruleId: 'P-60', severity: 'FLAG',
      message: `Cannot compute yield: input_kg=${input}, output_kg=${output}`,
      field: 'outputKg' });
  }
  const yieldPct = output / input;
  const range = await ctx.config.getYieldRange(outcome.processType, outcome.outputType);
  if (yieldPct < range.min || yieldPct > range.max) {
    return ctx.fail({ ruleId: 'P-60', severity: 'FLAG',
      message: `yield ${(yieldPct*100).toFixed(2)}% outside expected range [${(range.min*100).toFixed(2)}%, ${(range.max*100).toFixed(2)}%] for ${outcome.processType}/${outcome.outputType}`,
      field: 'outputKg' });
  }
  return ctx.pass({ ruleId: 'P-60' });
}

async function evaluate(ctx: RuleContext<'P-61'>): Promise<RuleResult> {
  const generatorId = ctx.input.generatorId;
  const monthStart = startOfMonth(ctx.input.month);
  const monthEnd = endOfMonth(ctx.input.month);
  const total = await ctx.db.massID.aggregate({
    _sum: { netKg: true },
    where: {
      participants: { some: { id: generatorId, role: 'G' }},
      completionDate: { gte: monthStart, lte: monthEnd },
      deletedAt: null,
    },
  });
  const value = total._sum.netKg ?? 0;
  const profile = await ctx.db.document.findFirst({ where: {
    participantId: generatorId, type: 'source_profile'
  }});
  if (!profile) {
    return ctx.fail({ ruleId: 'P-61', severity: 'FLAG',
      message: `No source_profile for Generator ${generatorId}; cannot validate monthly mass ${value}kg`,
      field: 'monthlyMass' });
  }
  const threshold = Number(profile.metadata?.threshold);
  if (value > threshold) {
    return ctx.fail({ ruleId: 'P-61', severity: 'FLAG',
      message: `Monthly mass ${value}kg exceeds threshold ${threshold}kg for Generator ${generatorId}`,
      field: 'monthlyMass' });
  }
  return ctx.pass({ ruleId: 'P-61' });
}

async function evaluate(ctx: RuleContext<'P-62'>): Promise<RuleResult> {
  const recyclerId = ctx.input.recyclerId;
  const monthStart = startOfMonth(ctx.input.month);
  const monthEnd = endOfMonth(ctx.input.month);
  const total = await ctx.db.massID.aggregate({
    _sum: { netKg: true },
    where: {
      participants: { some: { id: recyclerId, role: 'R' }},
      completionDate: { gte: monthStart, lte: monthEnd },
      deletedAt: null,
    },
  });
  const value = total._sum.netKg ?? 0;
  const profile = await ctx.db.document.findFirst({ where: {
    participantId: recyclerId, type: 'recycler_capacity_profile'
  }});
  if (!profile) {
    return ctx.fail({ ruleId: 'P-62', severity: 'FLAG',
      message: `No recycler_capacity_profile for ${recyclerId}; cannot validate input ${value}kg`,
      field: 'monthlyInput' });
  }
  const capacity = Number(profile.metadata?.capacity_value);
  const threshold = capacity * 1.05;
  if (value > threshold) {
    return ctx.fail({ ruleId: 'P-62', severity: 'FLAG',
      message: `Monthly input ${value}kg exceeds capacity ${capacity}kg (with 5% buffer) for Recycler ${recyclerId}`,
      field: 'monthlyInput' });
  }
  return ctx.pass({ ruleId: 'P-62' });
}

async function evaluate(ctx: RuleContext<'P-63'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.massidHash || !m.payloadHash) {
    return ctx.fail({ ruleId: 'P-63', severity: 'BLOCK',
      message: 'massid_hash or payload_hash missing', field: 'massidHash' });
  }
  const dupHash = await ctx.db.massID.findFirst({ where: {
    massidHash: m.massidHash,
    id: { not: m.id },
    deletedAt: null,
  }});
  if (dupHash) {
    return ctx.fail({ ruleId: 'P-63', severity: 'BLOCK',
      message: `Duplicate MassID hash collision with ${dupHash.id} (createdAt ${dupHash.createdAt.toISOString()})`,
      field: 'massidHash' });
  }
  const windowStart = subDays(m.completionDate ?? ctx.now, 60);
  const windowEnd = addDays(m.completionDate ?? ctx.now, 60);
  const dupPayload = await ctx.db.massID.findFirst({ where: {
    payloadHash: m.payloadHash,
    id: { not: m.id },
    completionDate: { gte: windowStart, lte: windowEnd },
    deletedAt: null,
  }});
  if (dupPayload) {
    return ctx.fail({ ruleId: 'P-63', severity: 'BLOCK',
      message: `Duplicate payload hash with MassID ${dupPayload.id} in ±60d window`,
      field: 'payloadHash' });
  }
  return ctx.pass({ ruleId: 'P-63' });
}

async function evaluate(ctx: RuleContext<'P-64'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.routeSignature) {
    return ctx.skip({ reason: 'No route signature (pickup w/o transport leg)' });
  }
  const windowStart = subDays(ctx.now, 7);
  const windowEnd = addDays(ctx.now, 7);
  const count = await ctx.db.massID.count({ where: {
    routeSignature: m.routeSignature,
    completionDate: { gte: windowStart, lte: windowEnd },
    deletedAt: null,
  }});
  const THRESHOLD = 3;
  if (count >= THRESHOLD) {
    return ctx.fail({ ruleId: 'P-64', severity: 'FLAG',
      message: `route_signature ${m.routeSignature} repeated ${count} times in ±7d window`,
      field: 'routeSignature' });
  }
  return ctx.pass({ ruleId: 'P-64' });
}

const VALID_TRANSITIONS: Record<string, string[]> = {
  CREATED: ['PICKED_UP'],
  PICKED_UP: ['IN_TRANSIT'],
  IN_TRANSIT: ['RECEIVED', 'EXCEPTION'],
  RECEIVED: ['SAMPLED', 'PROCESSED'],
  SAMPLED: ['PROCESSED'],
  PROCESSED: ['RECYCLED', 'EXCEPTION'],
  RECYCLED: [],
  EXCEPTION: ['IN_TRANSIT', 'RECEIVED']
};

async function evaluate(ctx: RuleContext<'P-65'>): Promise<RuleResult> {
  const events = await ctx.db.massIDEvent.findMany({
    where: { massidId: ctx.input.massidId, deletedAt: null },
    orderBy: { custodySeq: 'asc' }
  });
  if (events.length === 0) {
    return ctx.fail({ ruleId: 'P-65', severity: 'BLOCK',
      message: 'No MassIDEvents found for chain validation', field: 'events' });
  }
  // Check sequence gaps
  for (let i = 0; i < events.length; i++) {
    if (events[i].custodySeq !== i + 1) {
      return ctx.fail({ ruleId: 'P-65', severity: 'BLOCK',
        message: `custody_seq gap: expected ${i + 1}, got ${events[i].custodySeq}`,
        field: 'custodySeq' });
    }
  }
  // Check transitions
  for (let i = 1; i < events.length; i++) {
    const allowed = VALID_TRANSITIONS[events[i-1].toStatus] || [];
    if (!allowed.includes(events[i].toStatus)) {
      return ctx.fail({ ruleId: 'P-65', severity: 'BLOCK',
        message: `Invalid transition at seq ${events[i].custodySeq}: ${events[i-1].toStatus} → ${events[i].toStatus}`,
        field: 'status' });
    }
    if (events[i].timestamp < events[i-1].timestamp) {
      return ctx.fail({ ruleId: 'P-65', severity: 'BLOCK',
        message: `Timestamp out-of-order at seq ${events[i].custodySeq}`,
        field: 'timestamp' });
    }
  }
  // Check hash chain
  const chainValid = await ctx.crypto.verifyChain(events);
  if (!chainValid) {
    return ctx.fail({ ruleId: 'P-65', severity: 'BLOCK',
      message: 'Hash chain integrity check failed (events tampered or lost)',
      field: 'hashChain' });
  }
  return ctx.pass({ ruleId: 'P-65' });
}

async function evaluate(ctx: RuleContext<'P-66'>): Promise<RuleResult> {
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';

  const claim = await ctx.db.document.findOne({ where: {
    type: 'external_claim_check', massIdId: ctx.massId.id
  }});

  // Default seguro: sem flag = passa.
  if (!claim || claim.reviewStatus === 'false_positive') {
    return ctx.pass({ ruleId: 'P-66' });
  }

  if (claim.reviewStatus === 'confirmed') {
    // Bloqueia MassID atual.
    const result = ctx.fail({ ruleId: 'P-66', severity: sev,
      message: `Double-counting confirmado (source: ${claim.flagSource}, by: ${claim.reviewedBy})`,
      field: 'external_claim_check.reviewStatus' });

    // Dispara P-67 (Bad Actor propagation) — FLAG todos os MassIDs do mesmo participant.
    await ctx.dispatchRule({
      ruleId: 'P-67',
      participantId: ctx.massId.participantId,
      reason: `P-66 confirmed double-counting (MassID ${ctx.massId.id})`,
      scope: 'ALL_FROM_SAME_PARTICIPANT'
    });
    return result;
  }

  // reviewStatus = 'pending': aguarda decisão Compliance. Não bloqueia ainda.
  return ctx.flag({ ruleId: 'P-66', severity: 'FLAG',
    message: 'External claim em revisão pelo Compliance. Aguardando decisão.',
    field: 'external_claim_check.reviewStatus' });
}

async function evaluate(ctx: RuleContext<'P-67'>): Promise<RuleResult> {
  const incident = ctx.input.incident; // { massidId, severity, reason }
  if (incident.severity !== 'severe') {
    return ctx.skip({ reason: 'Incident not severe; no propagation' });
  }
  const linkedActors = await ctx.db.participant.findMany({ where: {
    massids: { some: { id: incident.massidId }}
  }});
  const linkedCredits = await ctx.db.trcCredit.findMany({ where: {
    massidId: incident.massidId
  }});
  // Mark all in exception state
  for (const a of linkedActors) {
    await ctx.db.participant.update({ where: { id: a.id }, data: { exceptionState: 'flagged', exceptionReason: incident.reason }});
  }
  for (const c of linkedCredits) {
    await ctx.db.trcCredit.update({ where: { id: c.id }, data: { status: 'HOLD', exceptionRef: incident.id }});
  }
  await ctx.audit.log({
    ruleId: 'P-67',
    action: 'propagation',
    affectedActors: linkedActors.map(a => a.id),
    affectedCredits: linkedCredits.map(c => c.id),
    reason: incident.reason,
  });
  return ctx.fail({ ruleId: 'P-67', severity: 'FLAG',
    message: `Bad actor propagation: ${linkedActors.length} actors + ${linkedCredits.length} credits placed in exception state due to ${incident.reason}`,
    field: 'exceptionState' });
}

async function evaluate(ctx: RuleContext<'PG-01'>): Promise<RuleResult> {
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';

  const rec = await ctx.db.document.findOne({ where: {
    type: 'kyc_kyb_record', participantId: ctx.participant.id
  }});
  // SKIP se P-03 já bloqueou — não tem o que validar.
  if (!rec) return ctx.skip({ ruleId: 'PG-01', reason: 'P-03 deve passar antes' });

  const errors: { field: string; reason: string }[] = [];

  // 1. Email — RFC 5322 simplificada
  if (rec.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rec.email)) {
    errors.push({ field: 'email', reason: `formato inválido: "${rec.email}"` });
  }

  // 2. Mobile — E.164 (international format)
  if (rec.mobile && !/^\+?[1-9]\d{1,14}$/.test(rec.mobile.replace(/[\s-()]/g, ''))) {
    errors.push({ field: 'mobile', reason: `não é E.164: "${rec.mobile}"` });
  }

  // 3. Birthdate — sanity check (18 ≤ idade ≤ 120)
  if (rec.birthdate) {
    const age = computeAge(rec.birthdate, ctx.now);
    if (age < 18) errors.push({ field: 'birthdate', reason: `menor de 18 anos (${age})` });
    if (age > 120) errors.push({ field: 'birthdate', reason: `idade implausível (${age})` });
  }

  // 4. taxId — checksum por jurisdição
  if (rec.taxId && rec.taxIdJurisdiction) {
    const valid = await ctx.validators.taxId.check(rec.taxId, rec.taxIdJurisdiction);
    if (!valid) errors.push({
      field: 'taxId', reason: `checksum inválido pra ${rec.taxIdJurisdiction}: "${rec.taxId}"`
    });
  }

  if (errors.length > 0) {
    return ctx.fail({
      ruleId: 'PG-01', severity: sev,
      message: `KYC com formato inválido: ${errors.map(e => e.field).join(', ')}`,
      field: 'kyc_kyb_record', metadata: { errors }
    });
  }
  return ctx.pass({ ruleId: 'PG-01' });
}

async function evaluate(ctx: RuleContext<'PG-02'>): Promise<RuleResult> {
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';
  const pickupAt = ctx.massId.pickupAt;
  const pending: { participantId: string; missing: string[] }[] = [];

  for (const link of ctx.massId.chain) {
    const consent = await ctx.db.document.findOne({ where: {
      type: 'participant_consent_record', participantId: link.participantId
    }});
    const missing: string[] = [];
    if (!consent) {
      missing.push('participant_consent_record_missing');
    } else {
      // Cada bundle (tc, dataRights) é revogável independentemente.
      for (const bundle of ['tcAcceptance', 'dataRightsAck'] as const) {
        const b = consent[bundle];
        if (!b) { missing.push(`${bundle}_missing`); continue; }
        // Versão MAJOR desatualizada → re-aceite obrigatório.
        const curMajor = ctx.config.currentTermsVersion[bundle].split('.')[0];
        const ackMajor = b.termsVersion.split('.')[0];
        if (curMajor !== ackMajor) {
          missing.push(`${bundle}_major_outdated`);
          continue;
        }
        // Non-retroactive revocation: pickup anterior à revogação é OK.
        if (pickupAt < b.acceptedAt) {
          missing.push(`${bundle}_accepted_after_pickup`);
        }
        if (b.revokeEffectiveAt && pickupAt >= b.revokeEffectiveAt) {
          missing.push(`${bundle}_revoked_before_pickup`);
        }
      }
    }
    if (missing.length > 0) pending.push({ participantId: link.participantId, missing });
  }

  if (pending.length > 0) {
    return ctx.fail({
      ruleId: 'PG-02', severity: sev,
      message: `${pending.length} participantes da cadeia sem aceite vivo válido.`,
      field: 'massId.chain.participants.consent',
      metadata: { pending }
    });
  }
  return ctx.pass({ ruleId: 'PG-02' });
}

async function evaluate(ctx: RuleContext<'PG-03'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  const strictJurisdictions = ctx.config.get('jurisdiction_aml_strict'); // ['EU', 'BR', 'US', 'UK']
  const isStrict = strictJurisdictions.includes(p.countryCode);
  if (p.amlCftAckFlag !== true) {
    const sev = isStrict ? 'BLOCK' : 'FLAG';
    return ctx.fail({ ruleId: 'PG-03', severity: sev,
      message: 'AML/CFT acknowledgement missing', field: 'amlCftAckFlag' });
  }
  return ctx.pass({ ruleId: 'PG-03' });
}

async function evaluate(ctx: RuleContext<'PG-04'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p.walletAddress || p.walletAddress.trim() === '') {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Wallet address missing', field: 'walletAddress' });
  }
  if (!ctx.crypto.isValidEvmAddress(p.walletAddress)) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Wallet address invalid format', field: 'walletAddress' });
  }
  const banned = ctx.config.get('jurisdiction_crypto_banned');
  if (banned.includes(p.countryCode)) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'BLOCK',
      message: 'Crypto rewards not allowed in jurisdiction', field: 'countryCode' });
  }
  if (p.digitalAssetLawAckFlag !== true) {
    return ctx.fail({ ruleId: 'PG-04', severity: 'FLAG',
      message: 'Digital asset law acknowledgement pending', field: 'digitalAssetLawAckFlag' });
  }
  return ctx.pass({ ruleId: 'PG-04' });
}

async function evaluate(ctx: RuleContext<'PG-05'>): Promise<RuleResult> {
  const int = await ctx.db.participant.findById(ctx.input.intId);
  if (!int || int.participantType !== 'INT') {
    return ctx.fail({ ruleId: 'PG-05', severity: 'BLOCK',
      message: 'Submitting actor is not an INT', field: 'participantType' });
  }
  if (int.intHomologationStatus !== 'active') {
    return ctx.fail({ ruleId: 'PG-05', severity: 'BLOCK',
      message: `INT homologation not active (status=${int.intHomologationStatus ?? 'null'})`,
      field: 'intHomologationStatus' });
  }
  if (!int.intHomologationExpiry || int.intHomologationExpiry < ctx.input.submissionDate) {
    return ctx.fail({ ruleId: 'PG-05', severity: 'BLOCK',
      message: `INT homologation expired on ${int.intHomologationExpiry?.toISOString() ?? 'never set'}`,
      field: 'intHomologationExpiry' });
  }
  return ctx.pass({ ruleId: 'PG-05' });
}

const ACCEPTED_DESTINATIONS = [
  'landfill',
  'open_dump',
  'incineration_no_recovery',
  'incineration_w_energy_recovery'
];

async function evaluate(ctx: RuleContext<'PG-06'>): Promise<RuleResult> {
  if (ctx.participant.role !== 'R') return ctx.skip({ ruleId: 'PG-06', reason: 'Não-Recycler' });

  const dest = ctx.participant.counterfactualDestination;
  const facilityName = ctx.participant.counterfactualFacilityName;

  if (!dest || !ACCEPTED_DESTINATIONS.includes(dest)) {
    return ctx.fail({ ruleId: 'PG-06', severity: 'BLOCK',
      message: 'counterfactualDestination ausente ou inválido (aceitos: landfill, open_dump, incineration_no_recovery, incineration_w_energy_recovery)',
      field: 'participant.counterfactualDestination' });
  }
  if (!facilityName) {
    return ctx.fail({ ruleId: 'PG-06', severity: 'BLOCK',
      message: 'Nome da instalação de destinação contrafactual ausente',
      field: 'participant.counterfactualFacilityName' });
  }

  // Open dump exige evidência adicional (foto geo-tagged + auditor visit) per PG-17
  if (dest === 'open_dump') {
    const dumpEvidence = await ctx.db.document.findOne({ where: {
      type: 'open_dump_evidence', participantId: ctx.participant.id
    }});
    if (!dumpEvidence) {
      return ctx.flag({ ruleId: 'PG-06', severity: 'FLAG',
        message: 'Open dump declarado mas open_dump_evidence ausente (fotografia geo-tagged + relatório auditor exigidos)',
        field: 'documents.open_dump_evidence' });
    }
  }

  // Incineração exige documentação da instalação receptora
  if (dest === 'incineration_no_recovery' || dest === 'incineration_w_energy_recovery') {
    const incinDoc = await ctx.db.document.findOne({ where: {
      type: 'incineration_facility_doc', participantId: ctx.participant.id
    }});
    if (!incinDoc) {
      return ctx.flag({ ruleId: 'PG-06', severity: 'FLAG',
        message: 'Incineração declarada mas incineration_facility_doc ausente',
        field: 'documents.incineration_facility_doc' });
    }
  }

  return ctx.pass({ ruleId: 'PG-06' });
}

async function evaluate(ctx: RuleContext<'PG-07'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (p.participantType !== 'R') return ctx.skip({ reason: 'Only applies to Recyclers.' });
  if (!p.recyclerCapacityEvidenceRef) {
    return ctx.fail({ ruleId: 'PG-07', severity: 'BLOCK',
      message: 'Recycler capacity evidence (business plan) missing',
      field: 'recyclerCapacityEvidenceRef' });
  }
  if (!p.recyclerCapacity || p.recyclerCapacity <= 0) {
    return ctx.fail({ ruleId: 'PG-07', severity: 'BLOCK',
      message: 'recyclerCapacity must be > 0', field: 'recyclerCapacity' });
  }
  const priorVolume = await ctx.db.recyclingOutcome.aggregate({
    _sum: { certifiedMassKg: true },
    where: { recyclerId: p.id, periodEnd: { gte: subPeriod(ctx.now, '12 months') } }
  });
  const prior = priorVolume._sum.certifiedMassKg ?? 0;
  if (prior > 0 && p.recyclerCapacity > prior * 1.20) {
    return ctx.fail({ ruleId: 'PG-07', severity: 'FLAG',
      message: `Declared capacity ${p.recyclerCapacity}kg exceeds 1.20× prior-period certified ${prior}kg; updated evidence required`,
      field: 'recyclerCapacity' });
  }
  return ctx.pass({ ruleId: 'PG-07' });
}

async function evaluate(ctx: RuleContext<'PG-08'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (p.participantType !== 'R') return ctx.skip({ reason: 'Only applies to Recyclers.' });
  if (p.certificationType !== 'full') {
    return ctx.skip({ reason: `certificationType=${p.certificationType} does not require prior volume evidence.` });
  }
  if (!p.recyclerPriorVolumeEvidenceRef) {
    return ctx.fail({ ruleId: 'PG-08', severity: 'BLOCK',
      message: 'Prior volume records (CDF/WDSR) missing for Full Certification',
      field: 'recyclerPriorVolumeEvidenceRef' });
  }
  if (!p.recyclerDeclaredAnnualVolumeKg || p.recyclerDeclaredAnnualVolumeKg <= 0) {
    return ctx.fail({ ruleId: 'PG-08', severity: 'BLOCK',
      message: 'recyclerDeclaredAnnualVolumeKg must be > 0',
      field: 'recyclerDeclaredAnnualVolumeKg' });
  }
  return ctx.pass({ ruleId: 'PG-08' });
}

async function evaluate(ctx: RuleContext<'PG-09'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!['R', 'P', 'INT'].includes(p.participantType)) return ctx.skip({ reason: 'Renewal only applies to R/P/INT.' });
  if (!p.homologationExpiry) {
    return ctx.fail({ ruleId: 'PG-09', severity: 'FLAG',
      message: 'homologationExpiry not set', field: 'homologationExpiry' });
  }
  const daysUntilExpiry = Math.floor((p.homologationExpiry.getTime() - ctx.now.getTime()) / (1000 * 60 * 60 * 24));
  if (daysUntilExpiry < 0) {
    return ctx.skip({ reason: 'Already expired — delegated to P-02 (BLOCK).' });
  }
  if (daysUntilExpiry <= 90) {
    return ctx.fail({ ruleId: 'PG-09', severity: 'FLAG',
      message: `Homologation expires in ${daysUntilExpiry} days; reach out to renew now`,
      field: 'homologationExpiry' });
  }
  return ctx.pass({ ruleId: 'PG-09' });
}

async function evaluate(ctx: RuleContext<'PG-10'>): Promise<RuleResult> {
  if (ctx.participant.role !== 'R') return ctx.skip({ ruleId: 'PG-10', reason: 'Não-Recycler' });
  const p = ctx.participant;

  const fields = [
    p.workforceLowIncomePct,
    p.workforceMinorityPct,
    p.workforceWomenPct,
    p.communityBenefitFlag
  ];

  const allNull = fields.every(f => f === null || f === undefined);
  if (allNull) {
    return ctx.flag({ ruleId: 'PG-10', severity: 'FLAG',
      message: 'Recycler sem dados sociais cadastrados (PURE §7.1.1 + §12)',
      field: 'participant.workforceSocial.*' });
  }

  // Zero-pattern detection: bad actor pode preencher tudo com 0 pra silenciar regra
  const headcount = p.workforceTotalHeadcount;
  const allZero = fields.every(f => f === 0 || f === false);
  if (headcount && headcount > 1 && allZero) {
    return ctx.flag({ ruleId: 'PG-10', severity: 'FLAG',
      message: 'Padrão suspeito: workforce > 1 mas todos os campos sociais = 0 (possível silenciamento da regra)',
      field: 'participant.workforceSocial.*',
      metadata: { suspicious_zero_pattern: true } });
  }

  return ctx.pass({ ruleId: 'PG-10' });
}

async function evaluate(ctx: RuleContext<'PG-11'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (m.weightCaptureMethod !== 'residential_average') return ctx.skip({ reason: 'Not residential_average method.' });
  if (m.pickupSourceType !== 'residential') {
    return ctx.fail({ ruleId: 'PG-11', severity: 'BLOCK',
      message: `residential_average not allowed for pickupSourceType=${m.pickupSourceType}`,
      field: 'weightCaptureMethod' });
  }
  if (!m.geoEvidenceRef) {
    return ctx.fail({ ruleId: 'PG-11', severity: 'BLOCK',
      message: 'geoEvidenceRef missing for residential_average pickup',
      field: 'geoEvidenceRef' });
  }
  const approvedAverages = await ctx.config.get('approved_averages_table');
  if (!m.residentialAvgRef || !approvedAverages.includes(m.residentialAvgRef)) {
    return ctx.fail({ ruleId: 'PG-11', severity: 'BLOCK',
      message: `residentialAvgRef '${m.residentialAvgRef}' not in approved averages table`,
      field: 'residentialAvgRef' });
  }
  return ctx.pass({ ruleId: 'PG-11' });
}

async function evaluate(ctx: RuleContext<'PG-12'>): Promise<RuleResult> {
  const int = await ctx.db.participant.findById(ctx.input.intId);
  if (int.participantType !== 'INT') return ctx.skip({ reason: 'Only applies to INTs.' });
  if (!int.intDataQualityFlag && !int.intSecurityBreachFlag) {
    return ctx.pass({ ruleId: 'PG-12' });
  }
  const linkedMassIds = await ctx.db.massID.findMany({
    where: { submittedByIntId: int.id, status: { notIn: ['EXCEPTION', 'RECYCLED'] } }
  });
  await ctx.db.massID.updateMany({
    where: { id: { in: linkedMassIds.map(m => m.id) } },
    data: { exceptionState: 'INT_POA_PROPAGATION' }
  });
  await ctx.db.participant.update({
    where: { id: int.id },
    data: { intHomologationStatus: 'suspended' }
  });
  return ctx.fail({ ruleId: 'PG-12', severity: 'BLOCK',
    message: `INT flagged (dataQuality=${int.intDataQualityFlag}, securityBreach=${int.intSecurityBreachFlag}); ${linkedMassIds.length} MassIDs moved to EXCEPTION; INT suspended`,
    field: 'intHomologationStatus' });
}

async function evaluate(ctx: RuleContext<'PG-13'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (!m.completionDate) {
    return ctx.fail({ ruleId: 'PG-13', severity: 'BLOCK',
      message: 'completionDate missing', field: 'completionDate' });
  }
  const currentYear = ctx.now.getUTCFullYear();
  const lowerBound = new Date(Date.UTC(currentYear - 1, 0, 1)); // Jan 1 prior year
  if (m.completionDate < lowerBound) {
    return ctx.fail({ ruleId: 'PG-13', severity: 'BLOCK',
      message: `completionDate ${m.completionDate.toISOString().slice(0,10)} is before lower bound ${lowerBound.toISOString().slice(0,10)} (Jan 1 prior calendar year)`,
      field: 'completionDate' });
  }
  return ctx.pass({ ruleId: 'PG-13' });
}

async function evaluate(ctx: RuleContext<'PG-14'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  const UNCERTAINTY_METHODS = ['manual', 'residential_average', 'visual_estimate'];
  if (!UNCERTAINTY_METHODS.includes(m.weightCaptureMethod)) {
    return ctx.skip({ reason: `Method ${m.weightCaptureMethod} uses calibration cert path.` });
  }
  if (m.measurementUncertaintyPct == null) {
    return ctx.fail({ ruleId: 'PG-14', severity: 'FLAG',
      message: `measurementUncertaintyPct required for ${m.weightCaptureMethod}`,
      field: 'measurementUncertaintyPct' });
  }
  if (m.measurementUncertaintyPct < 0 || m.measurementUncertaintyPct > 100) {
    return ctx.fail({ ruleId: 'PG-14', severity: 'FLAG',
      message: `measurementUncertaintyPct out of range (${m.measurementUncertaintyPct}); expected 0-100`,
      field: 'measurementUncertaintyPct' });
  }
  if (!m.measurementUncertaintyRef || m.measurementUncertaintyRef.trim() === '') {
    return ctx.fail({ ruleId: 'PG-14', severity: 'FLAG',
      message: 'measurementUncertaintyRef (supporting doc) missing',
      field: 'measurementUncertaintyRef' });
  }
  return ctx.pass({ ruleId: 'PG-14' });
}

async function evaluate(ctx: RuleContext<'PG-15'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (p.laborComplianceAckFlag !== true) {
