async function evaluate(ctx: RuleContext<'PG-17'>): Promise<RuleResult> {
  const m = await ctx.db.massID.findById(ctx.input.massidId);
  if (m.originClass !== 'open_dump') {
    return ctx.skip({ reason: 'Not open_dump origin.' });
  }
  if (!m.openDumpEvidenceRef || m.openDumpEvidenceRef.trim() === '') {
    return ctx.fail({ ruleId: 'PG-17', severity: 'BLOCK',
      message: 'open-dump origin requires openDumpEvidenceRef (geo-photos, registry, site report)',
      field: 'openDumpEvidenceRef' });
  }
  if (!m.auditorValidationRef || m.auditorValidationRef.trim() === '') {
    return ctx.fail({ ruleId: 'PG-17', severity: 'BLOCK',
      message: 'open-dump evidence must be validated by homologated third-party auditor (auditorValidationRef missing)',
      field: 'auditorValidationRef' });
  }
  const validation = await ctx.db.auditorValidation.findById(m.auditorValidationRef);
  if (!validation || !validation.auditorIsHomologated) {
    return ctx.fail({ ruleId: 'PG-17', severity: 'BLOCK',
      message: 'auditorValidationRef points to non-homologated auditor',
      field: 'auditorValidationRef' });
  }
  return ctx.pass({ ruleId: 'PG-17' });
}

async function evaluate(ctx: RuleContext<'PG-18'>): Promise<RuleResult> {
  const outcome = ctx.recyclingOutcome;
  if (!outcome.isBlend) return ctx.skip();
  if (!outcome.blendComposition || outcome.blendComposition.length === 0) {
    return ctx.fail({ ruleId: 'PG-18', severity: 'BLOCK',
      message: 'Blend composition missing: must declare % per source Ecoparque',
      field: 'blendComposition' });
  }
  const total = outcome.blendComposition.reduce((s, c) => s + c.percentage, 0);
  if (Math.abs(total - 100) > 0.5) {
    return ctx.fail({ ruleId: 'PG-18', severity: 'BLOCK',
      message: `Blend percentages sum to ${total}%, must be 100% (±0.5%)`,
      field: 'blendComposition' });
  }
  if (!outcome.blendAt) {
    return ctx.fail({ ruleId: 'PG-18', severity: 'BLOCK',
      message: 'Blend timestamp (date+time) missing',
      field: 'blendAt' });
  }
  for (const c of outcome.blendComposition) {
    const eco = await ctx.db.ecoparque.findById(c.ecoparqueId);
    if (!eco) return ctx.fail({ ruleId: 'PG-18', severity: 'BLOCK',
      message: `Ecoparque ${c.ecoparqueId} not found in source registry`,
      field: 'blendComposition.ecoparqueId' });
  }
  return ctx.pass({ ruleId: 'PG-18' });
}

async function evaluate(ctx: RuleContext<'PG-19'>): Promise<RuleResult> {
  const outcome = ctx.recyclingOutcome;
  const qcDoc = await ctx.db.document.findOne({ where: {
    type: 'output_qc_approval',
    relatedOutputBatchId: outcome.outputBatchId
  }});
  if (!qcDoc) {
    return ctx.fail({ ruleId: 'PG-19', severity: 'BLOCK',
      message: `Output QC approval document missing for batch ${outcome.outputBatchId}`,
      field: 'documents.output_qc_approval' });
  }
  if (!qcDoc.approverId || !qcDoc.approvalDate) {
    return ctx.fail({ ruleId: 'PG-19', severity: 'BLOCK',
      message: 'QC approval missing approver or approval date',
      field: 'output_qc_approval.approverId' });
  }
  if (qcDoc.validUntil && qcDoc.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'PG-19', severity: 'BLOCK',
      message: `Output QC approval expired on ${qcDoc.validUntil.toISOString()}`,
      field: 'output_qc_approval.validUntil' });
  }
  return ctx.pass({ ruleId: 'PG-19' });
}

async function evaluate(ctx: RuleContext<'PG-20'>): Promise<RuleResult> {
  const p = ctx.participant;
  const isProd = ctx.environment === 'production';
  const sev: 'BLOCK' | 'FLAG' = isProd ? 'BLOCK' : 'FLAG';
  const role = p.role;

  // Mapeamento role → doc_type esperado
  const REQUIRED_DOCS: Record<string, { type: string; renewalMonths: number; optional?: boolean }[]> = {
    'H': [{ type: 'hauler_license', renewalMonths: 24 }],
    'P': [{ type: 'environmental_operation_license', renewalMonths: 12 }],
    'R': [
      { type: 'environmental_operation_license', renewalMonths: 12 },
      { type: 'recyclass_certificate', renewalMonths: 12, optional: !p.recyclassOptIn }
    ],
    'INT': [{ type: 'integrator_contract', renewalMonths: 12 }]
  };

  const required = REQUIRED_DOCS[role] || [];
  if (required.length === 0) return ctx.skip({ ruleId: 'PG-20', reason: `Role ${role} sem accreditation requirement` });

  const missing: { docType: string; reason: string }[] = [];
  for (const req of required) {
    if (req.optional) continue;
    const doc = await ctx.db.document.findOne({ where: {
      type: req.type, participantId: p.id
    }});
    if (!doc) {
      missing.push({ docType: req.type, reason: 'missing' });
      continue;
    }
    if (doc.validUntil && doc.validUntil < ctx.now) {
      missing.push({ docType: req.type, reason: `expired on ${doc.validUntil.toISOString()}` });
    }
  }

  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'PG-20', severity: sev,
      message: `${missing.length} accreditation doc(s) ausente(s) ou expirado(s): ${missing.map(m=>m.docType).join(', ')}`,
      field: 'documents.accreditation',
      metadata: { missing } });
  }
  return ctx.pass({ ruleId: 'PG-20' });
}

async function evaluate(ctx: RuleContext<'EU-01'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const value = massid.ewcCode;
  if (value == null || String(value).trim() === '') {
    return ctx.fail({ ruleId: 'EU-01', severity: 'BLOCK',
      message: 'ewcCode is required (European Waste Catalogue)', field: 'ewcCode' });
  }
  const APPROVED = ctx.config.get('eu_ewc_codes');
  if (!APPROVED.includes(value)) {
    return ctx.fail({ ruleId: 'EU-01', severity: 'BLOCK',
      message: `ewcCode '${value}' not in approved EWC list`,
      field: 'ewcCode' });
  }
  return ctx.pass({ ruleId: 'EU-01' });
}

async function evaluate(ctx: RuleContext<'EU-02'>): Promise<RuleResult> {
  const massid = ctx.input.massid;
  const docs = await ctx.db.document.findMany({ where: {
    massidId: massid.id,
    type: { in: ['waste_transfer_note', 'annex_vii', 'pickup_record', 'processor_receipt', 'recycler_receipt'] }
  }});
  if (docs.length < 2) return ctx.skip({ reason: 'Only one doc — nothing to reconcile.' });
  const codes = new Set(docs.map(d => d.ewcCode).filter(Boolean));
  if (codes.size === 1) return ctx.pass({ ruleId: 'EU-02' });
  const reclass = await ctx.db.document.findFirst({ where: { massidId: massid.id, type: 'ewc_reclassification_record' }});
  if (reclass && reclass.justification && reclass.signedBy) {
    return ctx.pass({ ruleId: 'EU-02', note: 'reclassification justified' });
  }
  return ctx.fail({ ruleId: 'EU-02', severity: 'BLOCK',
    message: `EWC mismatch across chain: ${Array.from(codes).join(', ')} — no reclassification record on file`,
    field: 'ewcCode' });
}

async function evaluate(ctx: RuleContext<'EU-03'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const ewc = massid.ewcCode || '';
  const isHazByCode = ewc.trim().endsWith('*');
  const isHazByFlag = massid.hazardousFlag === true;
  if (isHazByCode || isHazByFlag) {
    return ctx.fail({ ruleId: 'EU-03', severity: 'BLOCK',
      message: `Hazardous waste excluded from PURE (ewcCode='${ewc}', hazardousFlag=${isHazByFlag})`,
      field: 'ewcCode' });
  }
  return ctx.pass({ ruleId: 'EU-03' });
}

async function evaluate(ctx: RuleContext<'EU-04'>): Promise<RuleResult> {
  const hauler = await ctx.db.participant.findOne({ where: { id: ctx.input.haulerId, type: 'H' }});
  const doc = await ctx.db.document.findFirst({ where: {
    participantId: hauler.id,
    type: 'carrier_licence'
  }});
  if (!doc) {
    return ctx.fail({ ruleId: 'EU-04', severity: 'BLOCK',
      message: 'carrier_licence document missing for Hauler', field: 'documents' });
  }
  const required = ['carrierLicenseNo', 'issuingAuthority', 'validTo'];
  const missing = required.filter(f => !doc[f] || String(doc[f]).trim() === '');
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-04', severity: 'BLOCK',
      message: `carrier_licence missing fields: ${missing.join(', ')}`,
      field: 'carrierLicenseNo' });
  }
  return ctx.pass({ ruleId: 'EU-04' });
}

async function evaluate(ctx: RuleContext<'EU-05'>): Promise<RuleResult> {
  const leg = await ctx.db.transportLeg.findById(ctx.input.transportLegId);
  const doc = await ctx.db.document.findFirst({ where: {
    participantId: leg.haulerId,
    type: 'carrier_licence'
  }});
  if (!doc) return ctx.skip({ reason: 'EU-04 will block.' });
  const td = leg.transportDate;
  if (doc.validFrom && td < doc.validFrom) {
    return ctx.fail({ ruleId: 'EU-05', severity: 'BLOCK',
      message: `Transport date ${td.toISOString()} before licence validFrom ${doc.validFrom.toISOString()}`,
      field: 'transportDate' });
  }
  if (doc.validTo && td > doc.validTo) {
    return ctx.fail({ ruleId: 'EU-05', severity: 'BLOCK',
      message: `Transport date ${td.toISOString()} after licence validTo ${doc.validTo.toISOString()}`,
      field: 'transportDate' });
  }
  return ctx.pass({ ruleId: 'EU-05' });
}

async function evaluate(ctx: RuleContext<'EU-06'>): Promise<RuleResult> {
  const leg = await ctx.db.transportLeg.findById(ctx.input.transportLegId);
  if (!leg.vehiclePlate || String(leg.vehiclePlate).trim() === '') {
    return ctx.fail({ ruleId: 'EU-06', severity: 'BLOCK',
      message: 'Vehicle plate missing on transport leg', field: 'vehiclePlate' });
  }
  const authorized = await ctx.db.authorizedVehicle.findFirst({ where: {
    haulerId: leg.haulerId, plate: leg.vehiclePlate, active: true
  }});
  if (!authorized) {
    return ctx.fail({ ruleId: 'EU-06', severity: 'BLOCK',
      message: `Vehicle plate '${leg.vehiclePlate}' not in Hauler's authorized_vehicle_register`,
      field: 'vehiclePlate' });
  }
  if (leg.pickupLat == null || leg.pickupLon == null) {
    return ctx.fail({ ruleId: 'EU-06', severity: 'BLOCK',
      message: 'Pickup GPS missing for vehicle event', field: 'pickupLat' });
  }
  const inside = await ctx.geo.isInsideRegisteredZone(leg.pickupLat, leg.pickupLon, leg.haulerId);
  if (!inside) {
    return ctx.fail({ ruleId: 'EU-06', severity: 'BLOCK',
      message: 'Pickup GPS outside any registered zone for this Hauler',
      field: 'pickupLat' });
  }
  return ctx.pass({ ruleId: 'EU-06' });
}

async function evaluate(ctx: RuleContext<'EU-07'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  if (!massid.domesticTransfer) return ctx.skip({ reason: 'not domestic' });
