  const missing = REQUIRED.filter(f => wtn.payload?.[f] == null || String(wtn.payload[f]).trim() === '');
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-08', severity: 'BLOCK',
      message: `WTN missing fields: ${missing.join(', ')}`,
      field: missing[0] });
  }
  return ctx.pass({ ruleId: 'EU-08' });
}

async function evaluate(ctx: RuleContext<'EU-09'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const wtn = await ctx.db.document.findFirst({ where: {
    massidId: massid.id,
    type: { in: ['waste_transfer_note', 'digital_equivalent'] }
  }});
  if (!wtn) return ctx.skip({ reason: 'EU-07 covers existence.' });
  const wtnParties = wtn.payload?.parties || {};
  const chain = { generatorId: massid.generatorId, haulerId: massid.haulerId, recyclerId: massid.recyclerId };
  const mismatches = [];
  for (const role of ['generatorId', 'haulerId', 'recyclerId']) {
    if (wtnParties[role] && chain[role] && wtnParties[role] !== chain[role]) {
      mismatches.push({ role, wtn: wtnParties[role], chain: chain[role] });
    }
  }
  if (mismatches.length) {
    return ctx.fail({ ruleId: 'EU-09', severity: 'BLOCK',
      message: `WTN parties mismatch MassID chain: ${mismatches.map(m => `${m.role} wtn=${m.wtn} vs chain=${m.chain}`).join('; ')}`,
      field: 'parties' });
  }
  return ctx.pass({ ruleId: 'EU-09' });
}

async function evaluate(ctx: RuleContext<'EU-10'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  if (!massid.crossBorder) return ctx.skip({ reason: 'not cross-border' });
