  return ctx.pass({ ruleId: 'EU-10' });
}

async function evaluate(ctx: RuleContext<'EU-11'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  if (!massid.crossBorder) return ctx.skip({ reason: 'not cross-border' });
  const annex = await ctx.db.document.findFirst({ where: {
    massidId: massid.id, type: 'annex_vii'
  }});
  if (!annex) return ctx.skip({ reason: 'EU-10 covers existence.' });
  const code = annex.payload?.recoveryOperationCode;
  const APPROVED = ['R1','R2','R3','R4','R5','R6','R7','R8','R9','R10','R11','R12','R13'];
  if (!code || String(code).trim() === '') {
    return ctx.fail({ ruleId: 'EU-11', severity: 'BLOCK',
      message: 'Recovery operation code missing in Annex VII',
      field: 'recoveryOperationCode' });
  }
  if (!APPROVED.includes(String(code).trim().toUpperCase())) {
    return ctx.fail({ ruleId: 'EU-11', severity: 'BLOCK',
      message: `Recovery code '${code}' invalid — must be R1..R13 (Annex II WFD). Disposal codes D1..D15 not allowed in PURE.`,
      field: 'recoveryOperationCode' });
  }
  return ctx.pass({ ruleId: 'EU-11' });
}

async function evaluate(ctx: RuleContext<'EU-12'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  if (!massid.crossBorder) return ctx.skip({ reason: 'not cross-border' });
  const annex = await ctx.db.document.findFirst({ where: { massidId: massid.id, type: 'annex_vii' }});
  if (!annex) return ctx.skip({ reason: 'EU-10 covers.' });
  const shipmentType = annex.payload?.shipmentType;
  const wasteClass = annex.payload?.wasteClass;
  const greenListed = ctx.config.get('eu_green_listed_codes'); // Annex III/IIIA/IIIB codes
  if (shipmentType === 'green_listed') {
    if (!greenListed.includes(massid.ewcCode)) {
      return ctx.fail({ ruleId: 'EU-12', severity: 'BLOCK',
        message: `Shipment declared green_listed but EWC '${massid.ewcCode}' not in Annex III/IIIA/IIIB`,
        field: 'shipmentType' });
    }
    return ctx.pass({ ruleId: 'EU-12' });
  }
  if (shipmentType === 'notification') {
    const consent = await ctx.db.document.findFirst({ where: {
      massidId: massid.id, type: 'notification_consent'
    }});
    if (!consent) {
      return ctx.fail({ ruleId: 'EU-12', severity: 'BLOCK',
        message: 'Notification-required shipment missing notification_consent document from competent authorities',
        field: 'documents' });
    }
    return ctx.pass({ ruleId: 'EU-12' });
  }
  return ctx.fail({ ruleId: 'EU-12', severity: 'BLOCK',
    message: `Shipment type '${shipmentType}' invalid — must be 'green_listed' or 'notification'`,
    field: 'shipmentType' });
}

async function evaluate(ctx: RuleContext<'EU-13'>): Promise<RuleResult> {
  const recycler = await ctx.db.participant.findOne({ where: { id: ctx.input.recyclerId, type: 'R' }});
  const permit = await ctx.db.document.findFirst({ where: {
    participantId: recycler.id, type: 'recycler_permit'
  }});
  if (!permit) {
    return ctx.fail({ ruleId: 'EU-13', severity: 'BLOCK',
      message: 'recycler_permit document missing', field: 'documents' });
  }
  if (permit.validUntil && permit.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'EU-13', severity: 'BLOCK',
      message: `recycler_permit expired on ${permit.validUntil.toISOString()}`,
      field: 'validUntil' });
  }
  const REQUIRED = ['permitNo', 'issuingAuthority', 'validTo', 'scope'];
  const missing = REQUIRED.filter(f => !permit[f] || String(permit[f]).trim() === '');
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-13', severity: 'BLOCK',
      message: `recycler_permit missing fields: ${missing.join(', ')}`,
      field: 'permitNo' });
  }
  return ctx.pass({ ruleId: 'EU-13' });
}

async function evaluate(ctx: RuleContext<'EU-14'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const permit = await ctx.db.document.findFirst({ where: {
    participantId: massid.recyclerId, type: 'recycler_permit'
  }});
  if (!permit) return ctx.skip({ reason: 'EU-13 will block.' });
  const ewc = massid.ewcCode;
  const scope = permit.scope || [];
  const matched = scope.some(s => ctx.ewc.matches(s, ewc)); // expande wildcards '15 01 *'
  if (!matched) {
    return ctx.fail({ ruleId: 'EU-14', severity: 'BLOCK',
      message: `EWC '${ewc}' not in recycler_permit scope: [${scope.join(', ')}]`,
      field: 'ewcCode' });
  }
  return ctx.pass({ ruleId: 'EU-14' });
}

async function evaluate(ctx: RuleContext<'EU-15'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  if (!massid.processorId) return ctx.skip({ reason: 'No processor in chain.' });
  const permit = await ctx.db.document.findFirst({ where: {
    participantId: massid.processorId, type: 'processor_permit'
  }});
