async function evaluate(ctx: RuleContext<'EU-16'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const events = await ctx.db.massidEvent.findMany({
    where: { massidId: massid.id }, orderBy: { occurredAt: 'asc' }
  });
  const chain = await ctx.db.getChainParticipants(massid.id); // [G, (P), H, R]
  const expected = ctx.custody.expectedEvents(chain);
  const actualKeys = events.map(e => `${e.fromParticipantId}->${e.toParticipantId}`);
  const missing = expected.filter(k => !actualKeys.includes(k));
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-16', severity: 'BLOCK',
      message: `Custody chain has ${missing.length} missing transfer(s): ${missing.join(', ')}`,
      field: 'custodyEvents' });
  }
  for (let i = 1; i < events.length; i++) {
    if (events[i-1].toParticipantId !== events[i].fromParticipantId) {
      return ctx.fail({ ruleId: 'EU-16', severity: 'BLOCK',
        message: `Custody discontinuity between events ${events[i-1].id} and ${events[i].id}`,
        field: 'custodyEvents' });
    }
  }
  return ctx.pass({ ruleId: 'EU-16' });
}

async function evaluate(ctx: RuleContext<'EU-17'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const docs = await ctx.db.document.findMany({ where: {
    massidId: massid.id, type: { in: ['waste_transfer_note', 'annex_vii', 'recycler_receipt', 'processor_receipt'] }
  }});
  const measurements = [massid.measuredKg, ...docs.map(d => d.payload?.quantityKg)].filter(v => v != null && v > 0);
  if (measurements.length < 2) return ctx.skip({ reason: 'Not enough measurements to reconcile.' });
  const min = Math.min(...measurements);
  const max = Math.max(...measurements);
  const tolerance = ctx.config.get('eu_mass_tolerance', 0.02); // 2%
  const drift = (max - min) / min;
  if (drift > tolerance) {
    return ctx.fail({ ruleId: 'EU-17', severity: 'BLOCK',
      message: `Mass inconsistency: ${measurements.join('kg, ')}kg — drift ${(drift*100).toFixed(2)}% > tolerance ${(tolerance*100)}%`,
      field: 'measuredKg' });
  }
  return ctx.pass({ ruleId: 'EU-17' });
}

async function evaluate(ctx: RuleContext<'EU-18'>): Promise<RuleResult> {
  const events = await ctx.db.massidEvent.findMany({
    where: { massidId: ctx.input.massidId },
    orderBy: { type: 'asc' }
  });
  const ORDER = ['pickup', 'transport_start', 'delivery', 'processing', 'recycling'];
  const dated = ORDER
    .map(t => events.find(e => e.type === t))
    .filter(e => e && e.occurredAt);
  for (let i = 1; i < dated.length; i++) {
    if (dated[i].occurredAt < dated[i-1].occurredAt) {
      return ctx.fail({ ruleId: 'EU-18', severity: 'BLOCK',
        message: `Date continuity violation: ${dated[i].type} (${dated[i].occurredAt.toISOString()}) before ${dated[i-1].type} (${dated[i-1].occurredAt.toISOString()})`,
        field: 'occurredAt' });
    }
  }
  return ctx.pass({ ruleId: 'EU-18' });
}

async function evaluate(ctx: RuleContext<'EU-19'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const checks = [
    { role: 'pickup', addressId: massid.pickupAddressId, participantId: massid.generatorId, allowed: ['G','B'] },
    { role: 'dropOff', addressId: massid.dropOffAddressId, participantId: massid.recyclerId, allowed: ['R'] },
    { role: 'recyclerSite', addressId: massid.recyclerSiteAddressId, participantId: massid.recyclerId, allowed: ['R'] }
  ];
  if (massid.processorId) {
    checks.push({ role: 'processingSite', addressId: massid.processingSiteAddressId, participantId: massid.processorId, allowed: ['P'] });
  }
  const mismatches = [];
  for (const c of checks) {
    if (!c.addressId) {
      mismatches.push({ role: c.role, reason: 'address missing' });
      continue;
    }
    const registered = await ctx.db.address.findOne({ where: { id: c.addressId, participantId: c.participantId, active: true }});
    if (!registered) mismatches.push({ role: c.role, addressId: c.addressId, expectedParticipantId: c.participantId });
  }
  if (mismatches.length) {
    return ctx.fail({ ruleId: 'EU-19', severity: 'BLOCK',
      message: `Address mismatch: ${JSON.stringify(mismatches)}`,
      field: 'addresses' });
  }
  return ctx.pass({ ruleId: 'EU-19' });
}

async function evaluate(ctx: RuleContext<'EU-20'>): Promise<RuleResult> {
  const doc = await ctx.db.document.findFirst({ where: {
    massidId: ctx.input.massidId, type: 'digital_equivalent'
  }});
  if (!doc) return ctx.skip({ reason: 'No digital doc.' });
  const schemaKey = doc.payload?.standard || 'DIWASS'; // ou 'eANV', 'FIR_DIGITAL'
  const schema = ctx.config.get(`digital_equivalent_schemas.${schemaKey}`);
  if (!schema) {
    return ctx.fail({ ruleId: 'EU-20', severity: 'BLOCK',
      message: `Unknown digital standard '${schemaKey}'`,
      field: 'standard' });
  }
  const missing = schema.requiredFields.filter(f => {
    const v = ctx.json.get(doc.payload, f);
    return v == null || String(v).trim() === '';
  });
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-20', severity: 'BLOCK',
      message: `Digital equivalent (${schemaKey}) missing required fields: ${missing.join(', ')}`,
      field: missing[0] });
  }
  return ctx.pass({ ruleId: 'EU-20' });
}

async function evaluate(ctx: RuleContext<'EU-21'>): Promise<RuleResult> {
  const doc = await ctx.db.document.findById(ctx.input.documentId);
  const REQUIRED = ['fileHash', 'versionNo', 'timestamp', 'massidId'];
  const missing = REQUIRED.filter(f => doc[f] == null || String(doc[f]).trim() === '');
  if (missing.length) {
    return ctx.fail({ ruleId: 'EU-21', severity: 'BLOCK',
      message: `Document integrity fields missing: ${missing.join(', ')}`,
      field: missing[0] });
  }
  const binary = await ctx.storage.read(doc.storagePath);
  const recomputed = ctx.crypto.sha256(binary);
  if (recomputed !== doc.fileHash) {
    return ctx.fail({ ruleId: 'EU-21', severity: 'BLOCK',
      message: `Document hash mismatch: stored=${doc.fileHash} vs recomputed=${recomputed} — possible tampering`,
      field: 'fileHash' });
  }
  return ctx.pass({ ruleId: 'EU-21' });
}

async function evaluate(ctx: RuleContext<'EU-22'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const logs = await ctx.db.auditLog.findMany({ where: {
    entityType: 'MassID', entityId: massid.id
  }, orderBy: { occurredAt: 'asc' }});
  if (logs.length === 0 || logs[0].action !== 'CREATE') {
    return ctx.fail({ ruleId: 'EU-22', severity: 'BLOCK',
      message: 'AuditLog missing CREATE entry for MassID', field: 'auditLog' });
  }
  const noActor = logs.filter(l => !l.actorId);
  if (noActor.length) {
    return ctx.fail({ ruleId: 'EU-22', severity: 'BLOCK',
      message: `${noActor.length} AuditLog entries without actorId attribution`,
      field: 'actorId' });
  }
  const expectedMutations = await ctx.audit.mutationsExpectedFor(massid);
  const actualMutations = logs.filter(l => l.action !== 'CREATE').length;
  if (actualMutations < expectedMutations) {
    return ctx.fail({ ruleId: 'EU-22', severity: 'BLOCK',
      message: `AuditLog incomplete: expected ${expectedMutations} mutations, got ${actualMutations}`,
      field: 'auditLog' });
  }
  return ctx.pass({ ruleId: 'EU-22' });
}

async function evaluate(ctx: RuleContext<'EU-23'>): Promise<RuleResult> {
  const leg = await ctx.db.transportLeg.findById(ctx.input.transportLegId);
  const straight = ctx.geo.haversineKm(leg.pickupLat, leg.pickupLon, leg.dropOffLat, leg.dropOffLon);
  if (leg.routeKm && leg.routeKm < straight - 1) {
    return ctx.fail({ ruleId: 'EU-23', severity: 'FLAG',
      message: `Route plausibility: declared route_km (${leg.routeKm}) less than straight-line distance (${straight.toFixed(1)})`,
      field: 'routeKm' });
  }
  if (leg.routeKm && straight > 0 && leg.routeKm > 3 * straight) {
    return ctx.fail({ ruleId: 'EU-23', severity: 'FLAG',
      message: `Route plausibility: route_km (${leg.routeKm}) > 3x straight-line (${straight.toFixed(1)})`,
      field: 'routeKm' });
  }
  if (leg.transitTimeMin && leg.routeKm) {
    const speedKmh = leg.routeKm / (leg.transitTimeMin / 60);
    if (speedKmh < 5 || speedKmh > 110) {
      return ctx.fail({ ruleId: 'EU-23', severity: 'FLAG',
        message: `Route plausibility: avg speed ${speedKmh.toFixed(1)} km/h implausible`,
        field: 'transitTime' });
    }
  }
  return ctx.pass({ ruleId: 'EU-23' });
}

async function evaluate(ctx: RuleContext<'EU-24'>): Promise<RuleResult> {
  const doc = await ctx.db.document.findById(ctx.input.documentId);
  if (doc.consolidated) return ctx.pass({ ruleId: 'EU-24', note: 'consolidated doc allowed' });
  const duplicates = await ctx.db.document.findMany({ where: {
    fileHash: doc.fileHash,
    id: { not: doc.id },
    massidId: { not: doc.massidId }
  }});
  if (duplicates.length > 0) {
    return ctx.fail({ ruleId: 'EU-24', severity: 'FLAG',
      message: `Duplicate document detected: same hash on ${duplicates.length} other MassID(s): ${duplicates.map(d => d.massidId).join(', ')}`,
      field: 'fileHash' });
  }
  return ctx.pass({ ruleId: 'EU-24' });
}

async function evaluate(ctx: RuleContext<'EU-25'>): Promise<RuleResult> {
  const leg = await ctx.db.transportLeg.findById(ctx.input.transportLegId);
  const vehicle = await ctx.db.authorizedVehicle.findFirst({ where: { plate: leg.vehiclePlate, haulerId: leg.haulerId }});
  if (!vehicle?.capacityKg) return ctx.skip({ reason: 'Vehicle capacity not declared.' });
  const massid = await ctx.db.massid.findById(leg.massidId);
  const carried = massid.measuredKg;
  const limit = vehicle.capacityKg * 1.05;
  if (carried > limit) {
    return ctx.fail({ ruleId: 'EU-25', severity: 'FLAG',
      message: `Volume vs capacity: carried ${carried}kg > vehicle capacity ${vehicle.capacityKg}kg (with 5% buffer = ${limit.toFixed(1)}kg)`,
      field: 'measuredKg' });
  }
  return ctx.pass({ ruleId: 'EU-25' });
}

async function evaluate(ctx: RuleContext<'EU-26'>): Promise<RuleResult> {
  const windowStart = ctx.dates.subPeriod(ctx.now, '30 days');
  const recyclerId = ctx.input.recyclerId;
  const permit = await ctx.db.document.findFirst({ where: {
    participantId: recyclerId, type: 'recycler_permit'
  }});
  if (!permit?.monthlyCapacityKg) return ctx.skip({ reason: 'No capacity declared.' });
  const total = await ctx.db.massid.aggregate({
    _sum: { processedKg: true },
    where: { recyclerId, processedAt: { gte: windowStart } }
  });
  const processed = total._sum.processedKg ?? 0;
  const limit = permit.monthlyCapacityKg * 1.10; // 10% buffer
  if (processed > limit) {
    return ctx.fail({ ruleId: 'EU-26', severity: 'FLAG',
      message: `Facility throughput: ${processed}kg processed in 30d > permit monthly capacity ${permit.monthlyCapacityKg}kg (with 10% buffer = ${limit.toFixed(0)}kg)`,
      field: 'processedKg' });
  }
  return ctx.pass({ ruleId: 'EU-26' });
}

async function evaluate(ctx: RuleContext<'RC-01'>): Promise<RuleResult> {
  const participant = await ctx.db.participant.findById(ctx.input.participantId);
  if (!participant) return ctx.fail({ ruleId: 'RC-01', severity: 'BLOCK',
    message: 'Participant not found', field: 'participantId' });
  if (!['R', 'P'].includes(participant.type) || participant.region !== 'EU') {
    return ctx.skip({ reason: 'Not applicable: RC-01 only applies to R/P in EU' });
  }
  const ref = participant.companyRegistrationRef;
  if (!ref || String(ref).trim() === '') {
    return ctx.fail({ ruleId: 'RC-01', severity: 'BLOCK',
      message: 'company_registration_ref is required',
      field: 'companyRegistrationRef' });
  }
  const doc = await ctx.db.document.findOne({ where: {
    participantId: participant.id, type: 'company_registration_doc' }});
  if (!doc) {
    return ctx.fail({ ruleId: 'RC-01', severity: 'BLOCK',
      message: 'company_registration_doc document missing', field: 'documents' });
  }
  if (doc.validUntil && doc.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'RC-01', severity: 'BLOCK',
      message: 'company_registration_doc expired on ' + doc.validUntil.toISOString(),
      field: 'documents.validUntil' });
  }
  if (doc.legalName && participant.legalName &&
      doc.legalName.trim().toLowerCase() !== participant.legalName.trim().toLowerCase()) {
    return ctx.fail({ ruleId: 'RC-01', severity: 'BLOCK',
      message: `legalName mismatch: '${participant.legalName}' vs doc '${doc.legalName}'`,
      field: 'legalName' });
  }
  return ctx.pass({ ruleId: 'RC-01' });
}

async function evaluate(ctx: RuleContext<'RC-02'>): Promise<RuleResult> {
  const windowStart = subPeriod(ctx.now, '12 months');
  const license = await ctx.db.recyclerLicense.findFirst({ where: {
    participantId: ctx.input.participantId, validUntil: { gte: ctx.now } }});
  if (!license) {
    return ctx.skip({ reason: 'No active RecyclerLicense; delegated to RC-01/permit rule.' });
  }
  const limit = license.licensedInputVolumeKg;
  const agg = await ctx.db.massID.aggregate({
    _sum: { massKg: true },
    where: { participantId: ctx.input.participantId,
             createdAt: { gte: windowStart }, deletedAt: null }});
  const total12m = agg._sum.massKg ?? 0;
  if (total12m > limit) {
    return ctx.fail({ ruleId: 'RC-02', severity: 'BLOCK',
      message: `sum of massKg (${total12m}kg) > licensedInputVolumeKg (${limit}kg) over 12 months`,
      field: 'massKg' });
  }
  if (total12m > 0.9 * limit) {
    return ctx.fail({ ruleId: 'RC-02', severity: 'FLAG',
      message: `sum of massKg (${total12m}kg) within 10% of license limit (${limit}kg) — renew or adjust capacity`,
      field: 'massKg' });
  }
  return ctx.pass({ ruleId: 'RC-02' });
}

async function evaluate(ctx: RuleContext<'RC-03'>): Promise<RuleResult> {
  const inv = await ctx.db.inventory.findFirst({ where: {
    participantId: ctx.input.participantId },
    orderBy: { snapshotDate: 'desc' }});
  const license = await ctx.db.recyclerLicense.findFirst({ where: {
    participantId: ctx.input.participantId, validUntil: { gte: ctx.now } }});
  if (!inv || !license) {
    return ctx.skip({ reason: 'Inventory snapshot or license missing.' });
  }
  const avg3m = (inv.stockLevelCurrentKg + inv.stockLevelM1Kg + inv.stockLevelM2Kg) / 3;
  const limit = license.licensedStorageVolumeKg;
  if (avg3m > 1.2 * limit) {
    return ctx.fail({ ruleId: 'RC-03', severity: 'BLOCK',
      message: `3-month avg stock (${avg3m.toFixed(0)}kg) > 120% of licensed storage (${limit}kg)`,
      field: 'stockLevelCurrentKg' });
  }
  if (avg3m > limit) {
    return ctx.fail({ ruleId: 'RC-03', severity: 'FLAG',
      message: `3-month avg stock (${avg3m.toFixed(0)}kg) > licensed storage limit (${limit}kg)`,
      field: 'stockLevelCurrentKg' });
  }
  return ctx.pass({ ruleId: 'RC-03' });
}

async function evaluate(ctx: RuleContext<'RC-04'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p || !['R', 'P'].includes(p.type) || p.region !== 'EU') {
    return ctx.skip({ reason: 'Not applicable.' });
  }
  if (!p.insurancePublicLiabilityRef || String(p.insurancePublicLiabilityRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-04', severity: 'BLOCK',
      message: 'insurance_public_liability_ref is required',
      field: 'insurancePublicLiabilityRef' });
  }
  const doc = await ctx.db.document.findOne({ where: {
    participantId: p.id, type: 'insurance_public_liability_cert' }});
  if (!doc) {
    return ctx.fail({ ruleId: 'RC-04', severity: 'BLOCK',
      message: 'insurance_public_liability_cert document missing', field: 'documents' });
  }
  if (doc.validUntil && doc.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'RC-04', severity: 'BLOCK',
      message: 'insurance_public_liability_cert expired on ' + doc.validUntil.toISOString(),
      field: 'documents.validUntil' });
  }
  // Sorting centres additionally need employer liability
  if (p.subType === 'sorting_centre') {
    const emp = await ctx.db.document.findOne({ where: {
      participantId: p.id, type: 'insurance_employer_liability_cert' }});
    if (!emp || (emp.validUntil && emp.validUntil < ctx.now)) {
      return ctx.fail({ ruleId: 'RC-04', severity: 'BLOCK',
        message: 'Sorting centre requires valid employer_liability insurance',
        field: 'insuranceEmployerLiabilityRef' });
    }
  }
  return ctx.pass({ ruleId: 'RC-04' });
}

