async function evaluate(ctx: RuleContext<'RC-09'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  const frequencyDays = p.stockSystemType === 'manual' ? 30 : 90;
  const windowStart = subPeriod(ctx.now, `${frequencyDays} days`);
  const inspections = await ctx.db.document.findMany({ where: {
    participantId: p.id, type: 'stock_inspection_record',
    documentDate: { gte: windowStart }}});
  if (inspections.length === 0) {
    return ctx.fail({ ruleId: 'RC-09', severity: 'FLAG',
      message: `No stock_inspection_record in last ${frequencyDays} days (required for stockSystemType=${p.stockSystemType})`,
      field: 'stockInspectionRecordRef' });
  }
  const highVariance = inspections.find(i => Math.abs(i.stockVariancePct ?? 0) > 5);
  if (highVariance) {
    return ctx.fail({ ruleId: 'RC-09', severity: 'FLAG',
      message: `Stock variance ${highVariance.stockVariancePct}% > 5% on inspection ${highVariance.documentDate.toISOString()}`,
      field: 'stockVariancePct' });
  }
  return ctx.pass({ ruleId: 'RC-09' });
}

const RANGE: Record<string, { kwhMin: number, kwhMax: number }> = {
  HDPE: { kwhMin: 500, kwhMax: 570 },
  PET:  { kwhMin: 220, kwhMax: 360 },
  // LDPE, PVC, PP marked 'To be assessed' — no range, skip range check
};

async function evaluate(ctx: RuleContext<'RC-10'>): Promise<RuleResult> {
  const out = await ctx.db.recyclingOutcome.findById(ctx.input.recyclingOutcomeId);
  const missing = [];
  if (out.energyKwhPerTonne == null) missing.push('energyKwhPerTonne');
  if (out.waterLitresPerTonne == null) missing.push('waterLitresPerTonne');
  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'RC-10', severity: 'FLAG',
      message: `Energy/water tracking incomplete: ${missing.join(', ')}`,
      field: missing[0] });
  }
  const range = RANGE[out.resinType];
  if (range && (out.energyKwhPerTonne < range.kwhMin || out.energyKwhPerTonne > range.kwhMax)) {
    return ctx.fail({ ruleId: 'RC-10', severity: 'FLAG',
      message: `Energy ${out.energyKwhPerTonne} kWh/t for ${out.resinType} outside RecyClass range [${range.kwhMin}-${range.kwhMax}]`,
      field: 'energyKwhPerTonne' });
  }
  return ctx.pass({ ruleId: 'RC-10' });
}

async function evaluate(ctx: RuleContext<'RC-11'>): Promise<RuleResult> {
  const out = await ctx.db.recyclingOutcome.findById(ctx.input.recyclingOutcomeId);
  const TOL_SPLIT = 0.1;  // 0.1 percentage points
  const TOL_CALC = 0.5;   // 0.5 percentage points vs computed

  if (out.recycledContentPct == null) {
    return ctx.fail({ ruleId: 'RC-11', severity: 'BLOCK',
      message: 'recycledContentPct required per EN 15343:2007 §6',
      field: 'recycledContentPct' });
  }
  if (out.preConsumerPct == null || out.postConsumerPct == null) {
    return ctx.fail({ ruleId: 'RC-11', severity: 'BLOCK',
      message: 'preConsumerPct and postConsumerPct must be reported separately (RecyClass §5.12)',
      field: 'preConsumerPct' });
  }
  const splitSum = out.preConsumerPct + out.postConsumerPct;
  if (Math.abs(splitSum - out.recycledContentPct) > TOL_SPLIT) {
    return ctx.fail({ ruleId: 'RC-11', severity: 'BLOCK',
      message: `pre(${out.preConsumerPct}) + post(${out.postConsumerPct}) = ${splitSum}% != recycledContentPct ${out.recycledContentPct}% (tol ${TOL_SPLIT}pp)`,
      field: 'recycledContentPct' });
  }
  if (out.totalOutputMassKg > 0) {
    const computed = (out.totalRecycledInputMassKg / out.totalOutputMassKg) * 100;
    if (Math.abs(computed - out.recycledContentPct) > TOL_CALC) {
      return ctx.fail({ ruleId: 'RC-11', severity: 'BLOCK',
        message: `recycledContentPct ${out.recycledContentPct}% does not match computed ${computed.toFixed(2)}% from masses (tol ${TOL_CALC}pp); denominator must include virgin + additives + masterbatch`,
        field: 'recycledContentPct' });
    }
  }
  return ctx.pass({ ruleId: 'RC-11' });
}

async function evaluate(ctx: RuleContext<'RC-12'>): Promise<RuleResult> {
  const auditType = ctx.input.auditType ?? 'monitoring'; // default monitoring
  if (auditType === 'initial') {
    return ctx.pass({ ruleId: 'RC-12', reason: 'Category 2 — not required at initial certification' });
  }
  const windowStart = subPeriod(ctx.now, '12 months');
  const records = await ctx.db.recyclingOutcome.findMany({ where: {
    participantId: ctx.input.participantId,
    createdAt: { gte: windowStart }}});
  const missing = records.filter(r => !r.endMarketCustomerName || !r.endMarketCountry || !r.endMarketApplication);
  if (missing.length === records.length && records.length > 0) {
    return ctx.fail({ ruleId: 'RC-12', severity: 'FLAG',
      message: `No end-market records for any of ${records.length} RecyclingOutcomes in last 12 months (Category 2 required at monitoring audit)`,
      field: 'endMarketCustomerName' });
  }
  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'RC-12', severity: 'FLAG',
      message: `${missing.length}/${records.length} RecyclingOutcomes missing end-market data`,
      field: 'endMarketCustomerName' });
  }
  return ctx.pass({ ruleId: 'RC-12' });
}

async function evaluate(ctx: RuleContext<'RC-13'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p || p.type !== 'R' || p.region !== 'EU') {
    return ctx.skip({ reason: 'Not applicable.' });
  }
  if (!p.pelletLossProcedureRef || String(p.pelletLossProcedureRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-13', severity: 'BLOCK',
      message: 'pellet_loss_procedure_ref required (Category 1 mandatory)',
      field: 'pelletLossProcedureRef' });
  }
  if (!p.pelletLossInspectionDate) {
    return ctx.fail({ ruleId: 'RC-13', severity: 'BLOCK',
      message: 'pellet_loss_inspection_date required',
      field: 'pelletLossInspectionDate' });
  }
  const twelveMonthsAgo = subPeriod(ctx.now, '12 months');
  if (p.pelletLossInspectionDate < twelveMonthsAgo) {
    return ctx.fail({ ruleId: 'RC-13', severity: 'BLOCK',
      message: `Last pellet loss inspection ${p.pelletLossInspectionDate.toISOString()} > 12 months ago — re-inspect`,
      field: 'pelletLossInspectionDate' });
  }
  return ctx.pass({ ruleId: 'RC-13' });
}

async function evaluate(ctx: RuleContext<'RC-14'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p || p.type !== 'R' || p.region !== 'EU') {
    return ctx.skip({ reason: 'Not applicable.' });
  }
  if (p.usesWaterInProcess !== true) {
    return ctx.pass({ ruleId: 'RC-14', reason: 'Dry process — wastewater rule does not apply' });
  }
  if (p.wastewaterDirectDischargeFlag === true) {
    return ctx.fail({ ruleId: 'RC-14', severity: 'BLOCK',
      message: 'Direct wastewater discharge without treatment is prohibited (RecyClass §7.3)',
      field: 'wastewaterDirectDischargeFlag' });
  }
  if (!p.wastewaterTreatmentRef || String(p.wastewaterTreatmentRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-14', severity: 'BLOCK',
      message: 'wastewater_treatment_ref required when usesWaterInProcess=TRUE',
      field: 'wastewaterTreatmentRef' });
  }
  const doc = await ctx.db.document.findOne({ where: {
    participantId: p.id, type: 'wastewater_treatment_license' }});
  if (!doc) {
    return ctx.fail({ ruleId: 'RC-14', severity: 'BLOCK',
      message: 'wastewater_treatment_license document missing',
      field: 'documents' });
  }
  if (doc.validUntil && doc.validUntil < ctx.now) {
    return ctx.fail({ ruleId: 'RC-14', severity: 'BLOCK',
      message: 'wastewater_treatment_license expired on ' + doc.validUntil.toISOString(),
      field: 'documents.validUntil' });
  }
  return ctx.pass({ ruleId: 'RC-14' });
}

const APPROVED_SCHEMES = ['RecyClass', 'EuCertPlast', 'PRE-recognised'];

async function evaluate(ctx: RuleContext<'RC-15'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  if (!massid.subcontractorId) {
    return ctx.skip({ reason: 'No subcontractor — RC-15 not applicable.' });
  }
  const sub = await ctx.db.subcontractedRecycling.findFirst({ where: {
    massidId: massid.id, subcontractorId: massid.subcontractorId }});
  if (!sub) {
    return ctx.fail({ ruleId: 'RC-15', severity: 'BLOCK',
      message: 'SubcontractedRecycling record missing for declared subcontractor',
      field: 'subcontractorId' });
  }
  if (!sub.subcontractorExternalCertRef || String(sub.subcontractorExternalCertRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-15', severity: 'BLOCK',
      message: 'subcontractor_external_cert_ref required (registry homologation alone is insufficient)',
      field: 'subcontractorExternalCertRef' });
  }
  if (!APPROVED_SCHEMES.includes(sub.subcontractorCertScheme)) {
    return ctx.fail({ ruleId: 'RC-15', severity: 'BLOCK',
      message: `subcontractor_cert_scheme '${sub.subcontractorCertScheme}' not in approved [${APPROVED_SCHEMES.join(', ')}]`,
      field: 'subcontractorCertScheme' });
  }
  const processingDate = massid.processingDate ?? massid.createdAt;
  if (sub.subcontractorCertExpiry < processingDate) {
    return ctx.fail({ ruleId: 'RC-15', severity: 'BLOCK',
      message: `subcontractor cert expired ${sub.subcontractorCertExpiry.toISOString()} before processing date ${processingDate.toISOString()}`,
      field: 'subcontractorCertExpiry' });
  }
  return ctx.pass({ ruleId: 'RC-15' });
}

async function evaluate(ctx: RuleContext<'RC-16'>): Promise<RuleResult> {
  const p = await ctx.db.participant.findById(ctx.input.participantId);
  if (!p || p.type !== 'R' || p.region !== 'EU') {
    return ctx.skip({ reason: 'Not applicable.' });
  }
  if (!p.reachComplianceProcedureRef || String(p.reachComplianceProcedureRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'reach_compliance_procedure_ref required (Category 1 mandatory)',
      field: 'reachComplianceProcedureRef' });
  }
  if (p.popComplianceFlag !== true && p.popComplianceFlag !== 'N/A') {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'pop_compliance_flag must be TRUE (or N/A with justification)',
      field: 'popComplianceFlag' });
  }
  if (p.popComplianceFlag === 'N/A' &&
      (!p.popComplianceJustification || String(p.popComplianceJustification).trim() === '')) {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'pop_compliance_flag=N/A requires popComplianceJustification',
      field: 'popComplianceJustification' });
  }
  if (p.reachNonConformityRef && !p.reachCorrectiveActionRef) {
    return ctx.fail({ ruleId: 'RC-16', severity: 'FLAG',
      message: 'REACH non-conformity registered without corrective action record',
      field: 'reachCorrectiveActionRef' });
  }
  return ctx.pass({ ruleId: 'RC-16' });
}

